// بيانات السور
Object.assign(quranData, {
    80: { // سورة عبس
        name: "عبس",
        basmalaTafsir: ``,
        verses: [
            { text: "عَبَسَ وَتَوَلَّىٰٓ", tafsir: `عثمان بن عفان ، أي قطّب وجهه ( وَتَوَلَّى ) أي أعرض.` },
            { text: "أَن جَآءَهُ ٱلْأَعْمَىٰ", tafsir: `أي بسبب أن جاءه شخص أعمى. قالوا وكان الأعمى ابن أم مكتوم. [4] ثم أخذ السياق لتأنيب عثمان بما فعله موجها الخطاب معه ، كما هو دأب القرآن في توجيه الخطاب إلى الناس ، نحو ( أَ أَنْتُمْ أَشَدُّ خَلْقاً ) (1) ( وَما يُدْرِيكَ ) أيها العابس ( لَعَلَّهُ يَزَّكَّى ) أي لعل الأعمى يتطهر بالعمل الصالح ؟ فيكون الإعراض عنه إثما ، حيث إنه إعراض عن الزاكي الطاهر.` },
            { text: "وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ", tafsir: `` },
            { text: "أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ", tafsir: `أي يتذكر بسبب الوعظ والإرشاد ، أصله « تذكر » ثم أدغمت التاء في الذال لقرب مخرجهما ، فجيء بهمزة الوصل لتعذر الابتداء بالساكن ( فَتَنْفَعَهُ الذِّكْرى ) ؟ والفرق بين الآيتين أن الأولى « زكاة » من نفسه ، والثانية « زكاة » بواسطة التذكير.` },
            { text: "أَمَّا مَنِ ٱسْتَغْنَىٰ", tafsir: `أي كان غنيا بالمال ، والإتيان من باب الاستفعال ، من جهة أن الشخص يطلب الغنى.` },
            { text: "فَأَنتَ لَهُۥ تَصَدَّىٰ", tafsir: `يا عابس ( لَهُ تَصَدَّى ) أي تتعرض ، أصله « تتصدى » حذفت إحدى تائيه على القاعدة ، أي تقبل عليه وتحاوره. ( 1) النازعات : 28. وَما عَلَيْكَ أَلاَّ يَزَّكَّى (7) وَأَمَّا مَنْ جاءَكَ يَسْعى (8) وَهُوَ يَخْشى (9) فَأَنْتَ عَنْهُ تَلَهَّى (10) كَلاَّ إِنَّها تَذْكِرَةٌ (11) فَمَنْ شاءَ ذَكَرَهُ (12) فِي صُحُفٍ مُكَرَّمَةٍ (13) مَرْفُوعَةٍ مُطَهَّرَةٍ (14)` },
            { text: "وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ", tafsir: `أي لا تبالي هل هو زكي أم لا ؟ فإن المال هو الذي يعظم في نفسك لا الدين ، ولذا لا تبالي بالدين إذا كان الشخص ذا مال.` },
            { text: "وَأَمَّا مَن جَآءَكَ يَسْعَىٰ", tafsir: `ساعيا لأجل الخير والرشد كابن أم مكتوم.` },
            { text: "وَهُوَ يَخْشَىٰ", tafsir: `الله عزوجل .` },
            { text: "فَأَنتَ عَنْهُ تَلَهَّىٰ", tafsir: `أيها العابس ( عَنْهُ ) عن ذلك الساعي ( تَلَهَّى ) أي تتلهى ـ على غرار تصدى ـ أي تتغافل وتشتغل بغيره ، لأنه فقير معدوم.` },
            { text: "كَلَّآ إِنَّهَا تَذْكِرَةٌ", tafsir: `ليس الأمر على ما زعمت : من أن المال خير من الدين ( إِنَّها ) أي هذه الآيات ( تَذْكِرَةٌ ) مذكرة بالحسن والقبيح الكامن في النفس والفطرة.` },
            { text: "فَمَن شَآءَ ذَكَرَهُۥ", tafsir: `الخير والسعادة ( ذَكَرَهُ ) أي ذكر ما أودع في نفسه وفطرته ، بأن عمل بالوعظ والإرشاد. [14] إن هذه التذكرة هي ( فِي صُحُفٍ مُكَرَّمَةٍ ) عند الله سبحانه ، والمراد « بالصحف » اللوح المحفوظ وسائر الألواح الموجودة في الملأ الأعلى.` },
            { text: "فِى صُحُفٍ مُّكَرَّمَةٍ", tafsir: `` },
            { text: "مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ", tafsir: `في السماء ـ حسا ـ أو معظمة مجللة ـ معنى ـ ( مُطَهَّرَةٍ ) أي منزهة من الخطأ والنقائص وما أشبهها. بِأَيْدِي سَفَرَةٍ (15) كِرامٍ بَرَرَةٍ (16) قُتِلَ الْإِنْسانُ ما أَكْفَرَهُ (17) مِنْ أَيِّ شَيْءٍ خَلَقَهُ (18) مِنْ نُطْفَةٍ خَلَقَهُ فَقَدَّرَهُ (19) ثُمَّ السَّبِيلَ يَسَّرَهُ (20)` },
            { text: "بِأَيْدِى سَفَرَةٍ", tafsir: `أي إن تلك الصحف إنما هي بأيدي الملائكة الكرام ، فإن « سفرة » جمع « سافر » وهو الكاتب ، أو السفير.` },
            { text: "كِرَامٍۭ بَرَرَةٍ", tafsir: `جمع كريم ، أي ذوي مقامات رفيعة ( بَرَرَةٍ ) جمع « بارّ » ، وهو المحسن. [18] ثم يأتي السياق ليتعجب من الكافر كيف يكفر بهذا الكتاب العظيم ، المنزل من عند الله سبحانه الذي هو الخالق وبيده أزمّة كل شيء ( قُتِلَ الْإِنْسانُ ) دعاء عليه ، أي اللهم أقتله ، والمراد به الجنس المنحرف بدلالة القرائن الآتية ( ما أَكْفَرَهُ ) ؟ تعجب من كفره وضلاله بعد وضوح الحجة وتمام المحجة.` },
            { text: "قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ", tafsir: `` },
            { text: "مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ", tafsir: `الله تعالى ؟ أي ألا ينظر إلى أصل خلقه كيف خلقه تعالى من ماء مهين ، حتى جعله إنسانا بهذه الغرابة في الدقة والأجهزة والآلات ؟` },
            { text: "مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ", tafsir: `أي قطرة من المني ( خَلَقَهُ فَقَدَّرَهُ ) أي قدر مزاياه وخصوصياته من حواسه ومشاعره وآلاته وأجهزته وكمه وكيفه وطوله وعرضه وغير ذلك.` },
            { text: "ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ", tafsir: `أي يسر وسهل له سبيل الحياة ، بأن هيأ له الأسباب والوسائل وأرشده إلى خيره وسعادته ، والأصل يسر له السبيل ثم حذف الجر ـ على قاعدة القطع والتوصيل ـ . ثُمَّ أَماتَهُ فَأَقْبَرَهُ (21) ثُمَّ إِذا شاءَ أَنْشَرَهُ (22) كَلاَّ لَمَّا يَقْضِ ما أَمَرَهُ (23) فَلْيَنْظُرِ الْإِنْسانُ إِلى طَعامِهِ (24) أَنَّا صَبَبْنَا الْماءَ صَبًّا (25) ثُمَّ شَقَقْنَا الْأَرْضَ شَقًّا (26) فَأَنْبَتْنا فِيها حَبًّا (27) وَعِنَباً وَقَضْباً (28)` },
            { text: "ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ", tafsir: `بعد أن انتهى أمده في الحياة ( أَماتَهُ ) بأن قبض روحه ( فَأَقْبَرَهُ ) أي أدخله القبر ، وهو المحل الذي يشتمل على جسمه بعد الموت ، وإن كان البحر أو نحوه ، أو من باب الغلبة.` },
            { text: "ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ", tafsir: `وأراد سبحانه قيام القيامة ( أَنْشَرَهُ ) أي بعثه حيا سويا. [24] فهل تراه تهيأ للنشور واستعد لذلك اليوم العظيم بالإيمان والعمل الصالح ؟ ( كَلَّا ) إنه في غفلة وسبات و ( لَمَّا يَقْضِ ) أي لم يأت بعد ب ( ما أَمَرَهُ ) الله سبحانه من الإيمان والعمل الصالح. [25] ثم يأتي السياق لتذكير الإنسان بجملة من الآيات الكونية تدليلا على وجوده سبحانه بالآيات الآفاقية بعد أن ذكره الآيات الأنفسية ( فَلْيَنْظُرِ الْإِنْسانُ إِلى طَعامِهِ ) الذي يأكله ، ليتذكر أصل الخلقة ، ومن خلقها ، ليرعوي عن غيّه وضلاله.` },
            { text: "كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ", tafsir: `` },
            { text: "فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ", tafsir: `` },
            { text: "أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا", tafsir: `المطر من السماء ( صَبًّا ) أي إنزالا.` },
            { text: "ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا", tafsir: `بإخراج النبات منها ( شَقًّا ) حتى أن النبات الضعيف خرج من الأرض الصلبة.` },
            { text: "فَأَنۢبَتْنَا فِيهَا حَبًّا", tafsir: `أي في الأرض ( حَبًّا ) أي جنس الحبوب من الحنطة والشعير وأمثالهما.` },
            { text: "وَعِنَبًا وَقَضْبًا", tafsir: `أنبتنا فيها ( عِنَباً ) خص بالذكر لكثرته ولذته وعظم فائدته ( وَقَضْباً ) وهو القت الرطب الذي يقضب ويقطع مرة بعد أخرى لعلف الدواب. وَزَيْتُوناً وَنَخْلاً (29) وَحَدائِقَ غُلْباً (30) وَفاكِهَةً وَأَبًّا (31) مَتاعاً لَكُمْ وَلِأَنْعامِكُمْ (32) فَإِذا جاءَتِ الصَّاخَّةُ (33) يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ (34)` },
            { text: "وَزَيْتُونًا وَنَخْلًا", tafsir: `وهو ما يعصر منه الزيت ( وَنَخْلاً ) وهو الشجرة التي تعطي التمر.` },
            { text: "وَحَدَآئِقَ غُلْبًا", tafsir: `جمع « حديقة » ، وهو البستان المحوّط بالسور أو البستان الصغير ذو الأشجار والأوراد ( غُلْباً ) جمع « غلباء » وهي الحديقة العظيمة الملتفة الأشجار ، كأنه مأخوذ من التغالب ، لتغالب أشجارها في الارتفاع للاستفادة من الهواء والضياء.` },
            { text: "وَفَٰكِهَةً وَأَبًّا", tafsir: `أي سائر ألوان الفواكه ( وَأَبًّا ) وهو المرعى من الحشيش وغيره الذي يرعاه الحيوان. [33] وإنما أنبتنا كل ذلك ( مَتاعاً لَكُمْ ) أي لأجل متاعكم وعيشكم ( وَلِأَنْعامِكُمْ ) أي بهائمكم. قالوا : الفاكهة لكم ، والأبّ لأنعامكم. [34] ثم ينتقل السياق من المبدأ إلى المعاد بقوله تعالى : ( فَإِذا جاءَتِ الصَّاخَّةُ ) وهي من أسامى القيامة ، بمعنى الصاكة ، لأنها تصك الأسماع ، أي تبالغ في إسماعها ، من أصواتها الشديدة ، كصوت النفخة ، وصوت النار ، وأصوات الملائكة ، وما أشبه. والجواب محذوف ، أي يكون الناس يومئذ قسمين ، وقد دل على الجواب ما يأتي في قوله « وجوه » . [35] ثم بين وقت مجيئها بقوله : وذلك ( يَوْمَ يَفِرُّ الْمَرْءُ ) أي كل أحد ( مِنْ أَخِيهِ ) خوفا بأن يبتلى به ، بأن يطلب منه شيئا ، أو يلقى عليه بعض تبعته. وَأُمِّهِ وَأَبِيهِ (35) وَصاحِبَتِهِ وَبَنِيهِ (36) لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ (37) وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌ (38) ضاحِكَةٌ مُسْتَبْشِرَةٌ (39) وَوُجُوهٌ يَوْمَئِذٍ عَلَيْها غَبَرَةٌ (40) تَرْهَقُها قَتَرَةٌ (41)` },
            { text: "مَّتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ", tafsir: `` },
            { text: "فَإِذَا جَآءَتِ ٱلصَّآخَّةُ", tafsir: `` },
            { text: "يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ", tafsir: `` },
            { text: "وَأُمِّهِۦ وَأَبِيهِ", tafsir: `حذرا من أن يكون قصر في حقهما ، أو يطالبانه بشيء.` },
            { text: "وَصَٰحِبَتِهِۦ وَبَنِيهِ", tafsir: `أي زوجته ، وهو من باب المثال ، وإلا فالزوجة أيضا تفر من زوجها ( وَبَنِيهِ ) أي أولاده ، والمراد إنه يفر من أعز أقربائه وعشرائه.` },
            { text: "لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ", tafsir: `أي من هؤلاء الفارين ، أو كل من حضر في القيامة ( يَوْمَئِذٍ شَأْنٌ ) أي أمر عظيم ( يُغْنِيهِ ) عن شؤون غيره لأنه مبتلى بحساب نفسه يشغله عن الاهتمام بالآخرين.` },
            { text: "وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ", tafsir: `أي يوم القيامة ، وهي وجوه المؤمنين ( مُسْفِرَةٌ ) أي مشرقة مضيئة ، « من أسفر » بمعنى ظهر فإنها تظهر عليها آثار الفرح والسرور.` },
            { text: "ضَاحِكَةٌ مُّسْتَبْشِرَةٌ", tafsir: `من السرور ( مُسْتَبْشِرَةٌ ) استبشرت بالخير والثواب أي فرحت وتهللت.` },
            { text: "وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ", tafsir: `أي يوم القيامة ، والمراد بها وجوه الكفار والعصاة ( عَلَيْها غَبَرَةٌ ) أي سواد وكآبة وحزن ، مشتق من الغبار وهو التراب المتصاعد الذي يعلو الأشياء.` },
            { text: "تَرْهَقُهَا قَتَرَةٌ", tafsir: `أي تعلو تلك الوجوه وتغشاها ( قَتَرَةٌ ) وهي ظلمة الدخان ، فالغبار والدخان وعبوس النفس كلها تظهر على وجوههم ، ولا يجليها رضوان الله ورحمته ، كما يجلي وجوه المؤمنين ، لو فرض أُولئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ (42) مرورها من محلات القيامة المغبرة.` },
            { text: "أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ", tafsir: `` }
        ]
    },
    81: { // سورة التكوير
        name: "التكوير",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا ٱلشَّمْسُ كُوِّرَتْ", tafsir: `أي ذهب نورها فأظلمت ، والتكوير هو اللف ، كأن المراد لف ضوؤها ، فذهب انبساطها في الآفاق ، فتصير سوداء مظلمة.` },
            { text: "وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ", tafsir: `بأن يذهب نورها وضياؤها ، من الكدرة.` },
            { text: "وَإِذَا ٱلْجِبَالُ سُيِّرَتْ", tafsir: `قلعها الله عن مكانها ، وسيرها كالهباء في الفضاء.` },
            { text: "وَإِذَا ٱلْعِشَارُ عُطِّلَتْ", tafsir: `وهي النوق الحوامل ، جمع « عشراء » وهي الناقة الحامل ، والناقة التي وضعت لتمام ( عُطِّلَتْ ) أي تركت هملا بلا راع ولا محافظ ، وذلك كناية عن أن أهوال ذلك اليوم بحيث توجب أن يذهل الإنسان عن أعز ماله.` },
            { text: "وَإِذَا ٱلْوُحُوشُ حُشِرَتْ", tafsir: `جمع وحش ، وهو الحيوان البري الذي لا يأنس ، أو مطلق الحيوان ( حُشِرَتْ ) أي جمعت في ذلك اليوم ليقتص للمظلوم منها من الظالم.` },
            { text: "وَإِذَا ٱلْبِحَارُ سُجِّرَتْ", tafsir: `أي حولت إلى النيران ، ومنه تسجير التنور ، بإيقاد النار فيه.` },
            { text: "وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ", tafsir: `بأن قرنت كل نفس إلى من يشاكلها فالمؤمن مع المؤمن ، والكافر مع الكافر ، أو زوجت نفوس المؤمنين بحور العين ونفوس الكافرين بالشياطين ، أو زوجت النفوس بالأحباء ، بعد وَإِذَا الْمَوْؤُدَةُ سُئِلَتْ (8) بِأَيِّ ذَنْبٍ قُتِلَتْ (9) وَإِذَا الصُّحُفُ نُشِرَتْ (10) وَإِذَا السَّماءُ كُشِطَتْ (11) وَإِذَا الْجَحِيمُ سُعِّرَتْ (12) وَإِذَا الْجَنَّةُ أُزْلِفَتْ (13) عَلِمَتْ نَفْسٌ ما أَحْضَرَتْ (14) مفارقتها عنها في حال الموت.` },
            { text: "وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ", tafsir: `من وئد بمعنى دفن الشيء حيا ، فقد كانت العرب تئد البنات خوف الفقر والعار ( سُئِلَتْ ) أي يسأل عنها.` },
            { text: "بِأَىِّ ذَنۢبٍ قُتِلَتْ", tafsir: `؟ يسأل عن الذين وأدوا بناتهم : بأي ذنب صدر منهن قتلتموهن ، وهن بريئات لا ذنب لهن ؟` },
            { text: "وَإِذَا ٱلصُّحُفُ نُشِرَتْ", tafsir: `أي صحائف أعمال الناس تنشر ليقرأها أصحابها ويطلعوا على ما فيها من خير وشر حتى يجازون بما عملوا.` },
            { text: "وَإِذَا ٱلسَّمَآءُ كُشِطَتْ", tafsir: `الكشط هو القلع عن شدة ، كأن السماء جلد يكشط ويقلع عن الكون ، وذلك كناية عن تبدل الأنظمة العلوية حتى يرى الإنسان السماء غير السماء كما يرى البدن المكشوط جلده بغير شكله السابق.` },
            { text: "وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ", tafsir: `أي النار ( سُعِّرَتْ ) أي أوقدت ، بأن ترتفع نارها ولهيبها لتشتد وتزداد حرارة وهولا.` },
            { text: "وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ", tafsir: `أي قربت ، كأنها في محل بعيد في الفضاء ثم تدنى إلى الأرض التي هي المحشر والموقف ، أو المراد قربت إلى المؤمنين قربا زمانيا. [15] إذا كانت هذه الأمور ( عَلِمَتْ نَفْسٌ ما أَحْضَرَتْ ) أي عرفت أعمالها فَلا أُقْسِمُ بِالْخُنَّسِ (15) الْجَوارِ الْكُنَّسِ (16) وَاللَّيْلِ إِذا عَسْعَسَ (17) وَالصُّبْحِ إِذا تَنَفَّسَ (18) إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ (19) التي عملتها في دار الدنيا من خير وشر وسعادة وشقاء والتي أحضرتها ليوم القيامة ، فإنها تعرف بأعمالها لتجازى عليها. [16] ثم جاء السياق لتثبيت أمر الرسالة وبيان أن القرآن ليس كلام الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ كما يزعم الكفار ـ ( فَلا أُقْسِمُ بِالْخُنَّسِ ) قد سبق أن « لا » للنفي ، وإنما يؤتى بها لنكتة هي إرادة تعظيم القسم والإشعار به مع عدم الحلف واقعا. كما تقوم لرجل عظيم « لا أقسم بحياتك لكن الأمر كذا » . و « الخنس » جمع الخانس ، وهو الذي يستتر ويرجع ، والمراد بها الكواكب ، أي لا أقسم بالكواكب التي تستتر عند مغيبها في المغرب ، أو لضياء النهار.` },
            { text: "عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ", tafsir: `` },
            { text: "فَلَآ أُقْسِمُ بِٱلْخُنَّسِ", tafsir: `` },
            { text: "ٱلْجَوَارِ ٱلْكُنَّسِ", tafsir: `جمع جارية ، لأن الكواكب تجري وتسير في السماء ( الْكُنَّسِ ) جمع « كانس » وهو الذي يستتر في محله ، كالضبي الذي يأوى إلى كناسه أي منزله ، وكأن المعنى لا أقسم بالكواكب السيارة التي ترجع في دورتها الفلكية وتجري وتختفي في أماكنها ، فإن أول الليل يرى الإنسان الكواكب رجعت عن مغيبها ، ثم يرى جريانها ثم اختفاءها عند المغرب أو عند إضاءة الصباح.` },
            { text: "وَٱلَّيْلِ إِذَا عَسْعَسَ", tafsir: `قسما ب ( اللَّيْلِ إِذا عَسْعَسَ ) أي أقبل ، أو بمعنى أدبر.` },
            { text: "وَٱلصُّبْحِ إِذَا تَنَفَّسَ", tafsir: `قسما ب ( الصُّبْحِ إِذا تَنَفَّسَ ) أي أسفر وأضاء. [20] ثم جاء متعلق الحلف بقوله : ( إِنَّهُ ) أي إن هذا القرآن ( لَقَوْلُ رَسُولٍ كَرِيمٍ ) المراد به جبرئيل عليه‌السلام ، في مقابل أن يكون من مخترعات ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ (20) مُطاعٍ ثَمَّ أَمِينٍ (21) وَما صاحِبُكُمْ بِمَجْنُونٍ (22) وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ (23) وَما هُوَ عَلَى الْغَيْبِ بِضَنِينٍ (24) وَما هُوَ بِقَوْلِ شَيْطانٍ رَجِيمٍ (25) الرسول ـ كما زعم الكفار ـ وكونه قول جبرئيل يراد به حكايته لذلك عن الله سبحانه ، لا إنه قوله الاستقلالي ـ كما لا يخفى ـ .` },
            { text: "إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ", tafsir: `` },
            { text: "ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍ", tafsir: `جسدية وعقلية ، فيتمكن من النزول من السماء إلى الأرض ، ويبلغ رسالة الله إلى الرسول كاملة بلا زيادة أو نقصان ( عِنْدَ ذِي الْعَرْشِ مَكِينٍ ) أي له مكان عظيم عند الله سبحانه ـ الذي هو صاحب العرش ، المالك للكون كله ، كما يقال للملك « صاحب العرش » كناية عن كونه ملكا ـ و « مكين » بمعنى متمكن. [22] وهو ( مُطاعٍ ) للملائكة ، أي يطيعونه الملائكة لكبر مقامه ( ثَمَ ) أي هناك في الملأ الأعلى ( أَمِينٍ ) على الوحي فلا يزيد فيه ولا ينقص. [23] فالقرآن إذا كلام الله تعالى ، أما الرسول ( وَما صاحِبُكُمْ ) أيها الكفار ـ والمراد به الرسول صلى‌الله‌عليه‌وآله‌وسلم الذي صحبهم ـ ( بِمَجْنُونٍ ) قد خلط عقله كما تتقوّلون عليه.` },
            { text: "مُّطَاعٍ ثَمَّ أَمِينٍ", tafsir: `` },
            { text: "وَمَا صَاحِبُكُم بِمَجْنُونٍ", tafsir: `` },
            { text: "وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ", tafsir: `أي رأى الرسول صلى‌الله‌عليه‌وآله‌وسلم جبرئيل ( بِالْأُفُقِ الْمُبِينِ ) في ناحية المشرق عند الأفق الواضح ، فلم يكن وهما أو إلقاء من الشياطين أو ما أشبه ـ كما تزعمون ـ .` },
            { text: "وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ", tafsir: `أي الرسول صلى‌الله‌عليه‌وآله‌وسلم ( عَلَى الْغَيْبِ ) أي وحي الله سبحانه له ( بِضَنِينٍ ) بمتهم ، من « الضنة » بمعنى التهمة ، أو ببخيل.` },
            { text: "وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍ رَّجِيمٍ", tafsir: `أي ليس القرآن ( بِقَوْلِ شَيْطانٍ رَجِيمٍ ) مرجوم أي مطرود فَأَيْنَ تَذْهَبُونَ (26) إِنْ هُوَ إِلاَّ ذِكْرٌ لِلْعالَمِينَ (27) لِمَنْ شاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ (28) وَما تَشاؤُنَ إِلاَّ أَنْ يَشاءَ اللهُ رَبُّ الْعالَمِينَ (29) باللعن ، كسائر الكهانات التي هي أقوال الشياطين تلقى على الكهنة.` },
            { text: "فَأَيْنَ تَذْهَبُونَ", tafsir: `أيها الكفار ؟ وكيف لا تؤمنون والقرآن شاهد صدق على نفسه ، بأنه ليس كلام مجنون ، ولا كلام شيطان ، ولا ما زيد فيه أو نقص لبخل الرسول بإعطاء الوحي كاملا ، فإنه من طرف المنزل ، وهو الله ، ومن طرف المنزل إليه وهو الرسول ، أحسن كتاب للهداية.` },
            { text: "إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ", tafsir: `أي ليس القرآن ( إِلَّا ذِكْرٌ لِلْعالَمِينَ ) أي لجميع الأجيال والعوالم ، عالم الإنس وعالم الجن ، يذكرهم بما أودع في فطرتهم من الأمور المرتبطة بالألوهية والرسالة والمعاد ، والأخلاق وما أشبه ذلك.` },
            { text: "لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ", tafsir: `أيها المكلفون ( أَنْ يَسْتَقِيمَ ) في عقيدته وعمله ، بأن لا ينحرف يمينا أو شمالا ، وإنما خصهم لأنهم المنتفعون بالذكر ، كما تقول « هذا معلم لمن شاء أن يتلمذ عنده » تعني أن المريد هو المستفيد منه ، وإن كان هو مستعد لتعليم كل فرد.` },
            { text: "وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ", tafsir: `` }
        ]
    },
    82: { // سورة الإنفطار
        name: "الإنفطار",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ", tafsir: `أي انشقت وظهر فيها أثر الانفطار حتى إذا شاهدها الإنسان رآها كالحائط المنفطر.` },
            { text: "وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ", tafsir: `أي تهافتت واختلفت أمكنتها وبطل نظامها الحالي ، من النثر وهو التبعثر.` },
            { text: "وَإِذَا ٱلْبِحَارُ فُجِّرَتْ", tafsir: `كما تتفجر العيون ، بأن أخذت تغلي بالماء أو باللهب.` },
            { text: "وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ", tafsir: `أي قلب ترابها لخروج الأموات منها ، والشيء المبعثر هو المتفرق. [6] إذا صار كل ذلك ، فقد قامت القيامة و ( عَلِمَتْ ) كل ( نَفْسٌ ) والمراد بالنفس الجنس ، ولذا أدخلنا عليها « كل » ( ما قَدَّمَتْ وَأَخَّرَتْ ) أي يعرف كل إنسان ـ بالنظر إلى صحيفة عمله ـ ما قدم إلى الآخرة في حال كونه في الدنيا وما أخر إلى الآخرة بعد وفاته ، بما خلف من صدقات جارية وكتب علم ودين أو أشياء ضارة وما أشبه ذلك ، فإنه يعرف بكل ذلك ليجزي حسب ما عمل إن حسنا فحسن ، وإن سيئا فسيء. [7] ثم يأتي السياق لإيقاظ الإنسان من نومه ، بقوله : ( يا أَيُّهَا الْإِنْسانُ ما غَرَّكَ بِرَبِّكَ الْكَرِيمِ ) ؟ أي أيّ شيء خدعك بربك حتى صرت تعصيه الَّذِي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ (7) فِي أَيِّ صُورَةٍ ما شاءَ رَكَّبَكَ (8) كَلاَّ بَلْ تُكَذِّبُونَ بِالدِّينِ (9) وَإِنَّ عَلَيْكُمْ لَحافِظِينَ (10) وتخالفه ، آمنا من عذابه وعقابه ؟ وهل كان من العدل أن تقابل كرمه بالعصيان ؟ وهل جزاء الإحسان إلا الإحسان ؟ ـ و في حديث أن النبي صلى‌الله‌عليه‌وآله‌وسلم لما تلا هذه الآية قال : غره جهله (1) .` },
            { text: "عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ", tafsir: `` },
            { text: "ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ", tafsir: `بأن أوجدك منيا ( فَسَوَّاكَ ) جعل أجهزتك سليمة معدة لمنافعها ( فَعَدَلَكَ ) أي جعل بعض أعضائك عدل بعض كعينين ويدين ورجلين وما أشبه بحيث يتناسب أحدهما مع الآخر دون كبر في بعض وصغر في بعض.` },
            { text: "فِىٓ أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ", tafsir: `« ما » زائدة لتأكيد اختلاف الصور ( رَكَّبَكَ ) أي ركبك في أية صورة شاء من أنواع الصور الحسنة والقبيحة والمليحة أو غيرها وهكذا ، فإن بسائط الجسم من لحم وعظم وشحم ودم وغيرها ركب سبحانه منها صورة كل إنسان بشكل خاص. [10] فهل بعد ذلك كله تنكرون وجود الله ، أو قدرته على البعث ( كَلَّا ) ليس الأمر على ما تزعمون ( بَلْ تُكَذِّبُونَ بِالدِّينِ ) أي بالجزاء لا تؤمنون ، بل تكذبون. [11] وتظنون أن لا حساب ( وَإِنَّ عَلَيْكُمْ ) أيها الناس ( لَحافِظِينَ ) من الملائكة ، يحفظون أعمالكم بكتابتها في دواوين لتجزون عليها يوم القيامة ، و « حافظين » اسم « إنّ » . ( 1) بحار الأنوار : ج 7 ص 94. كِراماً كاتِبِينَ (11) يَعْلَمُونَ ما تَفْعَلُونَ (12) إِنَّ الْأَبْرارَ لَفِي نَعِيمٍ (13) وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ (14) يَصْلَوْنَها يَوْمَ الدِّينِ (15) وَما هُمْ عَنْها بِغائِبِينَ (16) وَما أَدْراكَ` },
            { text: "كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ", tafsir: `` },
            { text: "وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ", tafsir: `` },
            { text: "كِرَامًا كَٰتِبِينَ", tafsir: `أي ملائكة كراما ذوي رفعة ومكانة رفيعة ( كاتِبِينَ ) يكتبون أعمال بني آدم. [13] ولا يسقط من حسابهم شيء ، بل ( يَعْلَمُونَ ) كل ( ما تَفْعَلُونَ ) من طاعة ومعصية وخير وشر. [14] ثم في يوم القيامة يجازى كل حسب ما عمل ( إِنَّ الْأَبْرارَ ) جمع « بر » وهو المحسن في العقيدة والعمل ( لَفِي نَعِيمٍ ) الجنان ورفاهها وخيرها.` },
            { text: "يَعْلَمُونَ مَا تَفْعَلُونَ", tafsir: `` },
            { text: "إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ", tafsir: `` },
            { text: "وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍ", tafsir: `جمع « فاجر » وهو العامل بالمعاصي ، كفرا كان أو غيره ( لَفِي جَحِيمٍ ) اسم من أسامي جهنم ، وهي النار الكثيرة.` },
            { text: "يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ", tafsir: `أي يدخلونها ملازمين لها ( يَوْمَ الدِّينِ ) أي يوم القيامة.` },
            { text: "وَمَا هُمْ عَنْهَا بِغَآئِبِينَ", tafsir: `أي الفجار ( عَنْها ) أي عن الجحيم ( بِغائِبِينَ ) بأن يغيبوا عن النار في بعض الأوقات ، بل إنهم مؤبدون فيها بلا انقطاع. [18] وإذا تقدم ذكر يوم القيامة جاء السياق لتهويل شأنه ( وَما أَدْراكَ ) أيها الإنسان ( ما يَوْمُ الدِّينِ ) ؟ أي أيّ شيء هو ؟ فإن أهوالها لا تدرك ، حتى يراها الإنسان رأي العين.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ", tafsir: `` },
            { text: "ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ", tafsir: `لترتيب الكلام وتكثير التهويل ( ما أَدْراكَ ) أيها الإنسان ما يَوْمُ الدِّينِ (17) ثُمَّ ما أَدْراكَ ما يَوْمُ الدِّينِ (18) يَوْمَ لا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئاً وَالْأَمْرُ يَوْمَئِذٍ لِلَّهِ (19) ( ما يَوْمُ الدِّينِ ) ؟ أي ما هو الجزاء. [20] إنه ( يَوْمَ لا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئاً ) ، فلا يقدر أحد الدفاع عن غيره ، أو إنقاذه بسائر الوسائل ( وَالْأَمْرُ يَوْمَئِذٍ ) أي في ذلك اليوم ( لِلَّهِ ) وحده ، ولا ينفع للنجاة إلا العمل الصادر لله تعالى. (83)` },
            { text: "يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا وَٱلْأَمْرُ يَوْمَئِذٍ لِّلَّهِ", tafsir: `` }
        ]
    },
    83: { // سورة المطففين
        name: "المطففين",
        basmalaTafsir: ``,
        verses: [
            { text: "وَيْلٌ لِّلْمُطَفِّفِينَ", tafsir: `وهي كلمة تقال بمعنى سوء الحال ، أي أن سوء الحال ( لِلْمُطَفِّفِينَ ) و « التطفيف » هو نقص الكيل والميزان. [3] ثم فسره سبحانه بقوله : ( الَّذِينَ إِذَا اكْتالُوا عَلَى النَّاسِ ) أي كالوا ما على الناس ليأخذوه لأنفسهم ، كما لو دفعوا مالا لاشتراء من من الحنطة ، فإذا كالوها ( يَسْتَوْفُونَ ) أي يأخذون بمقدار حقهم وافيا ، ولما كان الكيل والوزن من جنس واحد اكتفى بأحدهما عن ذكر الآخر.` },
            { text: "ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ", tafsir: `` },
            { text: "وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ", tafsir: `أي كالوا لهم ( أَوْ وَزَنُوهُمْ ) أي وزنوا لهم ، بأن أرادوا بيع من من الحنطة مثلا للناس وقبض الثمن لأنفسهم ( يُخْسِرُونَ ) أي ينقصون فيما يعطون ، فمثلا ينقصون من المنّ حقة. ولا يخفى أن العمل الأول ليس محرما ، وإنما يكون بشعا إذا قيس بالعمل الثاني ، كما أن إطراء الناس في وجههم ليس محرما ، ولكن إذا ضم إلى ذمهم في قفاهم صار بشعا ، وسمي الفاعل لذلك ذا لسانين ، وكان له يوم القيامة لسانان من نار ـ كما ورد ـ . [5] ثم يأتي السياق ليهددهم بقوله : ( أَ لا يَظُنُ ) والإتيان بلفظ الظن لإفادة أن مجرد الظن كاف في الانقطاع ، فكيف بالعلم ( أُولئِكَ ) المطففون ( أَنَّهُمْ مَبْعُوثُونَ ) ، أي يبعثون.` },
            { text: "أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ", tafsir: `` },
            { text: "لِيَوْمٍ عَظِيمٍ", tafsir: `في يوم القيامة الذي يحاسب فيه كل إنسان بما عمل. يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعالَمِينَ (6) كَلاَّ إِنَّ كِتابَ الفُجَّارِ لَفِي سِجِّينٍ (7) وَما أَدْراكَ ما سِجِّينٌ (8) كِتابٌ مَرْقُومٌ (9) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (10) الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ (11) [7] وهو ( يَوْمَ يَقُومُ النَّاسُ ) من قبورهم ( لِرَبِّ الْعالَمِينَ ) أي لحسابه وجزائه.` },
            { text: "يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍ", tafsir: `ليس الأمر على ما زعمتم من أنه لا حساب ولا جزاء ، بل هناك يجازي كل إنسان بما عمل ، ف ( إِنَّ كِتابَ الفُجَّارِ ) جمع فاجر ، وهو العاصي لله سبحانه ، سواء كان بالكفر أو الإثم ، والمراد بكتابهم ما أدرج فيه أسماؤهم وخصوصياتهم ( لَفِي سِجِّينٍ ) وهو السجل على جهة التخليد فيه ، يعني أنه قرر لهم السجن الأبدي ، وهكذا سجل أسماؤهم بأنهم في سجين ، كما تقول : « كتاب فلان في المجرمين » أي أنه كتب مجرما في ضمن سائر المجرمين. [9] ثم جاء السياق لتهويل أمر سجين بقوله : ( وَما أَدْراكَ ) أيها الإنسان ، أو يا رسول الله ( ما سِجِّينٌ ) ؟ فما أعلمك به ، بل أنتم لا تدرون به. [10] إنما هو ( كِتابٌ مَرْقُومٌ ) قد رقم وكتب وفرغ منه ، فلا يمكن تبديله وتغييره ، بأن يمحي اسم الفاجر منه ، ليدرج في كتاب الأبرار.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا سِجِّينٌ", tafsir: `` },
            { text: "كِتَٰبٌ مَّرْقُومٌ", tafsir: `` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) . [12] ثم حدد معنى المكذبين ، والمراد بهم بقوله : ( الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ ) أي بيوم القيامة ، فإن الدين بمعنى الجزاء ، والتكذيب بيوم القيامة يلازم التكذيب بسائر الأصول. وَما يُكَذِّبُ بِهِ إِلاَّ كُلُّ مُعْتَدٍ أَثِيمٍ (12) إِذا تُتْلى عَلَيْهِ آياتُنا قالَ أَساطِيرُ الْأَوَّلِينَ (13) كَلاَّ بَلْ رانَ عَلى قُلُوبِهِمْ ما كانُوا يَكْسِبُونَ (14) كَلاَّ إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ (15)` },
            { text: "ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ", tafsir: `` },
            { text: "وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ", tafsir: `أي بيوم القيامة ( إِلَّا كُلُّ مُعْتَدٍ ) يعتدي ويظلم ويتجاوز عن الحد ( أَثِيمٍ ) يأثم ويعصي في كثرة ويبالغ في الاعتداء.` },
            { text: "إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ", tafsir: `أي تقرأ على ذلك المعتدي ( آياتُنا ) الدالة على الألوهية والتوحيد وسائر الأصول ، أو المراد بها القرآن ( قالَ ) هذه التي تتلونها هي ( أَساطِيرُ الْأَوَّلِينَ ) حكاياتهم وكلماتهم الخرافية ، جمع « أسطورة » وهي القصة الخيالية التي لا حقيقة لها ، وفي هذا اليوم يسمون الدين « رجعية » عبارة أخرى عن « أساطير الأولين » .` },
            { text: "كَلَّا بَلْ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ", tafsir: `ليست الآيات أساطير ( بَلْ رانَ عَلى قُلُوبِهِمْ ) « الرين » في الأصل بمعنى الغلبة ، أي غلب عليها ( ما كانُوا يَكْسِبُونَ ) من الذنوب والآثام ، حتى أن عصيانهم سبّب تحجّر قلبهم ، فلا يرون الحق إلا باطلا ، والآيات إلا أساطير. قال الصادق عليه‌السلام : يصدأ القلب ، فإذا ذكرته بالله انجلى (1) .` },
            { text: "كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ", tafsir: `لا يبقى هؤلاء في خير ونعيم إلى الأبد ، كما يظن الكفار بأنهم هناك أيضا يحظون بكرامة الله وإحسانه قائلين ( وَلَئِنْ رُدِدْتُ إِلى رَبِّي لَأَجِدَنَّ خَيْراً مِنْها مُنْقَلَباً ) (2) ( إِنَّهُمْ عَنْ رَبِّهِمْ ) أي عن لطفه ورحمته ( يَوْمَئِذٍ ) أي في يوم القيامة ( لَمَحْجُوبُونَ ) ممنوعون ، وهذا كما ( 1) مجمع البيان : ج 10 ص 293. ( 2) الكهف : 37. ثُمَّ إِنَّهُمْ لَصالُوا الْجَحِيمِ (16) ثُمَّ يُقالُ هذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ (17) كَلاَّ إِنَّ كِتابَ الْأَبْرارِ لَفِي عِلِّيِّينَ (18) وَما أَدْراكَ ما عِلِّيُّونَ (19) كِتابٌ مَرْقُومٌ (20) يَشْهَدُهُ الْمُقَرَّبُونَ (21) تقول « حجبني فلان عن الملك » أي منع لطفه عني.` },
            { text: "ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ", tafsir: `بعد أن حجبوا عن فضل الله ولطفه ( لَصالُوا الْجَحِيمِ ) أي داخلون فيها ملازمون لها.` },
            { text: "ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ", tafsir: `لهم بعد أن دخلوا الجحيم على وجه التقريع والتوبيخ ( هذَا الَّذِي ) ذقتموه من العذاب والنكال ( كُنْتُمْ بِهِ ) في الدنيا ( تُكَذِّبُونَ ) وتقولون : لا جنة ، ولا نار ، ولا حساب ، ولا جزاء.` },
            { text: "كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ", tafsir: `ليس الأمر كما زعمتم من أنكم أهل كرامة الله ، إن الكرامة ليست لكم ، وإنما هي للأبرار ( إِنَّ كِتابَ الْأَبْرارِ ) أي الكتاب الذي أدرج فيه أسماؤهم وعين فيه مقاماتهم ، و « أبرار » جمع برّ وهو المحسن عقيدة وعملا ( لَفِي عِلِّيِّينَ ) أي مراتب عالية ، فإنهم مكتوبون في سجلهم أن مقامهم هناك. [20] ثم جاء السياق لتعظيم مقامهم بقوله : ( وَما أَدْراكَ ) أيها الإنسان ، أو يا رسول الله ( ما ) هي ( عِلِّيُّونَ ) ؟ [21] إنه ( كِتابٌ مَرْقُومٌ ) قد رقم وسجل فلا يمحى عنه أسماء الأبرار.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ", tafsir: `` },
            { text: "كِتَٰبٌ مَّرْقُومٌ", tafsir: `` },
            { text: "يَشْهَدُهُ ٱلْمُقَرَّبُونَ", tafsir: `أي يعرفه ويعلم مزاياه ( الْمُقَرَّبُونَ ) أي الملائكة المقربون ، وفي ذلك كرامة أخرى للأبرار ، لأن الإنسان يجب أن يطلع الناس وغيرهم على أعماله الحسنة. إِنَّ الْأَبْرارَ لَفِي نَعِيمٍ (22) عَلَى الْأَرائِكِ يَنْظُرُونَ (23) تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ (24) يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ (25) خِتامُهُ مِسْكٌ وَفِي ذلِكَ فَلْيَتَنافَسِ الْمُتَنافِسُونَ (26) [23] ثم جاء القياس يعين مكان الأبرار الذي كتب في كتابهم أنهم في عليين ( إِنَّ الْأَبْرارَ لَفِي نَعِيمٍ ) في الملاذ والمشتهيات. [24] وهم جالسون ( عَلَى الْأَرائِكِ ) جمع أريكة ، وهي كرسي العروس الذي تجلس عليه ( يَنْظُرُونَ ) إلى هنا وهناك ليلتذوا بالنظر كما التذوا بسائر أنواع الحواس.` },
            { text: "إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ", tafsir: `` },
            { text: "عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ", tafsir: `` },
            { text: "تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ", tafsir: `أيها الإنسان ، إذا نظرت إلى أولئك الأبرار ( فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ ) أي بريقه وحسنه وجماله ، فإن الإنسان الذي في نعمة وراحة يظهر على وجهه بريق ولمعان ونضارة.` },
            { text: "يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ", tafsir: `والساقي هم الملائكة بأمره سبحانه ( مِنْ رَحِيقٍ ) هو الشراب الخالص من كل كدورة وفساد ( مَخْتُومٍ ) قد ختم على آنيته بعد أن سد رأسه ، لئلا يصيبه الأذى من الخارج ، كالمربيات والأشربة التي تقفل وتختم في العلب في الدنيا.` },
            { text: "خِتَٰمُهُۥ مِسْكٌ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ", tafsir: `فإن المداد الذي يختم به على أواني الرحيق من المسك المذاب ، وفي ذلك تشويق وأناقة ودلالة على النعيم وكثرة الرفاه ( وَفِي ذلِكَ ) النعيم ( فَلْيَتَنافَسِ الْمُتَنافِسُونَ ) أي فليرغب الراغبون بالمبادرة إلى طاعة الله سبحانه ، وأصل التنافس التزاحم على الشيء ، إن نعيم الجنة هو القابل لأن يتزاحم فيه الناس ، وذلك بأن يبادر إلى كل الأعمال الصالحة لينالها ، لا أن يتنازعوا في ملذات الدنيا وَمِزاجُهُ مِنْ تَسْنِيمٍ (27) عَيْناً يَشْرَبُ بِهَا الْمُقَرَّبُونَ (28) إِنَّ الَّذِينَ أَجْرَمُوا كانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ (29) وَإِذا مَرُّوا بِهِمْ يَتَغامَزُونَ (30) فإنها زائلة فانية.` },
            { text: "وَمِزَاجُهُۥ مِن تَسْنِيمٍ", tafsir: `أي الشيء الذي مزج بذلك الرحيق ( مِنْ ) عين تسمى بال ( تَسْنِيمٍ ) وهي عين جيدة ، سميت بالتسنيم لارتفاعها ، من سنم بمعنى ارتفع. [29] في حال كون ذلك التسنيم ( عَيْناً ) أو منصوب على المدح ( يَشْرَبُ بِهَا ) أي منها ( الْمُقَرَّبُونَ ) الذين قربوا إلى رضوان الله تعالى بأعمالهم الصالحة. [30] ثم يأتي ليبين أن ما يراه المجرم والمحسن هناك إنما هو جزاء أعمالهم ( إِنَّ الَّذِينَ أَجْرَمُوا ) أي فعلوا الجرائم والآثام في دار الدنيا ( كانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ ) على وجه السخرية بهم والاستهزاء لهم ، و « من » ابتدائية ، كأن ضحكهم كان يبتدئ وينشأ من طرف المؤمنين ، وهذا حكاية عن أحوالهم وهم في الدنيا وكأن الحكاية في الآخرة حين يعاتب المجرمين ويثاب المحسنون.` },
            { text: "عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ", tafsir: `` },
            { text: "وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ", tafsir: `أي المؤمنون ( بِهِمْ ) أي بالمجرمين ( يَتَغامَزُونَ ) بأن يشير بعضهم إلى بعض بالعين والحاجب استهزاء بالمؤمنين ، ومن المعلوم أن الإمام أمير المؤمنين عليه‌السلام كان ممن يتغامز به المنافقون ولذا ورد في بعض الروايات تفسير الآية بذلك (1) ، وهو من باب المصداق. ( 1) بحار الأنوار : ج 18 ص 172. وَإِذَا انْقَلَبُوا إِلى أَهْلِهِمُ انْقَلَبُوا فَكِهِينَ (31) وَإِذا رَأَوْهُمْ قالُوا إِنَّ هؤُلاءِ لَضالُّونَ (32) وَما أُرْسِلُوا عَلَيْهِمْ حافِظِينَ (33) فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ (34) عَلَى الْأَرائِكِ يَنْظُرُونَ (35) هَلْ ثُوِّبَ الْكُفَّارُ ما كانُوا يَفْعَلُونَ (36)` },
            { text: "وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ", tafsir: `أي رجع أولئك المجرمون ( إِلى أَهْلِهِمُ ) أي إلى بيوتهم ( انْقَلَبُوا ) ورجعوا في حال كونهم ( فَكِهِينَ ) الفكه هو المرح الأشر ، أي متلذذين بالسخرية منهم ، كما هو شأن الجهلاء دائما.` },
            { text: "وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ", tafsir: `أي رأى المجرمون ، المؤمنين ( قالُوا ) أي قال بعضهم لبعض ( إِنَّ هؤُلاءِ ) المؤمنين ( لَضالُّونَ ) عن طريق الصواب حيث تركوا نعيم الدنيا ، بزعم نعيم الآخرة « وهل عاقل باع الوجود بدين » ؟` },
            { text: "وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ", tafsir: `الحال أن الكفار ( ما أُرْسِلُوا عَلَيْهِمْ ) أي على المؤمنين ( حافِظِينَ ) أعمالهم ويشهدون برشدهم وضلالهم.` },
            { text: "فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ", tafsir: `أي يوم القيامة ( الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ ) جزاء وفاقا كما ضحك الكفار منهم في الدنيا ، فإن بعض الأحوال السيئة لشخص يوجب ضحك الطرف المقابل.` },
            { text: "عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ", tafsir: `جمع أريكة وهو الكرسي المعد لجلوس العروس ( يَنْظُرُونَ ) أي ينظر المؤمنون إلى الكفار ، وهم في النار يتقلبون. [37] ثم يأتي بالمستهزئين جزاء استهزائهم بالمؤمنين في الدنيا ( هَلْ ثُوِّبَ الْكُفَّارُ ) أي أثيبوا وجوزوا ( ما كانُوا يَفْعَلُونَ ) في الدنيا ؟ نعم أثيبوا وها هم في النار يتقلبون. (84)` },
            { text: "هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ", tafsir: `` }
        ]
    },
    84: { // سورة الإنشقاق
        name: "الإنشقاق",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ", tafsir: `أي تصدّعت وانفرجت ، كما ينشق الحائط فيظهر للعين في السماء لون الانفطار والانشقاق ، وتتناثر النجوم لاختلال النظام.` },
            { text: "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ", tafsir: `السماء ( لِرَبِّها ) أي خالقها ، والمراد انقادت لله سبحانه ، وأصل الإذن الاستماع ، يقال « أذن فلان لأمري » أي استمع ، واستعمل مجازا بمعنى الانقياد بعلاقة السبب والمسبب ( وَحُقَّتْ ) أي وحق لها أن تأذن وتنقاد ، وإنما جيء بالمجهول لأن المعنى أنها جعلت حقيقة بالانقياد ، بأن خلقت بكيفية تنقاد وتطيع الأمر.` },
            { text: "وَإِذَا ٱلْأَرْضُ مُدَّتْ", tafsir: `أي بسطت باندكاك جبالها حتى تصير كالصحيفة الملساء فتوسع لأنه لا عوج فيها ولا أمت.` },
            { text: "وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ", tafsir: `أي أخرجت ما في جوفها من الكنوز والمعادن والأموات ( وَتَخَلَّتْ ) أي خلت فلم يبق في بطنها شيء.` },
            { text: "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ", tafsir: `أي انقادت الأرض ( لِرَبِّها ) الله سبحانه ( وَحُقَّتْ ) لها أن تأذن بالإطاعة والانقياد ، والجواب ل « إذا » محذوف ، أي انقسم الناس إلى قسمين ناج وهالك ، يدل على ذلك قوله « فأما من » الآتية. [7] ثم توجه الخطاب إلى الإنسان ليستعد لهذا اليوم المهول ( يا أَيُّهَا الْإِنْسانُ إِنَّكَ كادِحٌ إِلى رَبِّكَ كَدْحاً ) « الكدح » هو السعي الشديد في الأمر ، أي سعى إلى ربّه ـ أي إلى جزائه وحسابه ـ سعيا شديدا ، فإن فَمُلاقِيهِ (6) فَأَمَّا مَنْ أُوتِيَ كِتابَهُ بِيَمِينِهِ (7) فَسَوْفَ يُحاسَبُ حِساباً يَسِيراً (8) وَيَنْقَلِبُ إِلى أَهْلِهِ مَسْرُوراً (9) وَأَمَّا مَنْ أُوتِيَ كِتابَهُ وَراءَ ظَهْرِهِ (10) فَسَوْفَ يَدْعُوا ثُبُوراً (11) وَيَصْلى سَعِيراً (12) الإنسان لا يزال يسعى في الأرض بجهد وشدة ـ إذ الدنيا دار تعب وعناء ـ حتى ينتهي إلى حساب الله سبحانه ( فَمُلاقِيهِ ) أي تلاقي كدحك ـ بمعنى جزاء عملك ـ عند ما صرت إلى حساب ربك.` },
            { text: "يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَٰقِيهِ", tafsir: `` },
            { text: "فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ", tafsir: `أي أعطي ( كِتابَهُ ) الذي كتبه الملكان ، المدروج فيه أعماله ( بِيَمِينِهِ ) أي بيده اليمنى ، وذلك دليل السعادة والفلاح.` },
            { text: "فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا", tafsir: `بعده بمدة ( يُحاسَبُ حِساباً يَسِيراً ) سهلا بلا أتعاب ونقاش ، ولعل المدة بين إعطاء الكتاب وبين الحساب طويل ولذا جيء ب « سوف » .` },
            { text: "وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا", tafsir: `أي يرجع من محل المحاسبة ( إِلى أَهْلِهِ ) الذين حوسبوا قبله وانتظروا مقدمه ، أو المراد حور العين التي أعدت له ( مَسْرُوراً ) فرحا.` },
            { text: "وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ", tafsir: `بأن يأخذ الملائكة بيده اليسرى إلى وراء ظهره ثم يعطى كتابه هناك ، تكثيرا للخزي والفضاحة وإيذانا بأنه من أهل النار والعذاب.` },
            { text: "فَسَوْفَ يَدْعُوا۟ ثُبُورًا", tafsir: `أي هلاكا ، إذا قرأ كتابه فيقول « وا ثبوراه » أي يا هلاك احضر فهذا وقتك.` },
            { text: "وَيَصْلَىٰ سَعِيرًا", tafsir: `أي يدخل النار المستعرة الملتهبة ، ملازما لها. إِنَّهُ كانَ فِي أَهْلِهِ مَسْرُوراً (13) إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ (14) بَلى إِنَّ رَبَّهُ كانَ بِهِ بَصِيراً (15) فَلا أُقْسِمُ بِالشَّفَقِ (16) وَاللَّيْلِ وَما وَسَقَ (17) وَالْقَمَرِ إِذَا اتَّسَقَ (18) لَتَرْكَبُنَّ طَبَقاً عَنْ طَبَقٍ (19)` },
            { text: "إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا", tafsir: `أي هذا المجرم ( كانَ فِي أَهْلِهِ ) في الدنيا ( مَسْرُوراً ) بما أوتي من أمور الدنيا فلا يهتم بأمر الآخرة ، بخلاف من يهتم بأمر الآخرة فإنه حزين لأنه لا يدري ماذا يصنع به ، وما تكون عاقبته.` },
            { text: "إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ", tafsir: `في الدنيا ( أَنْ لَنْ يَحُورَ ) أي لن يرجع إلى حال الحياة بعد الموت ، من حار : بمعنى رجع.` },
            { text: "بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا", tafsir: `يرجع ، وظنه فاسد ( إِنَّ رَبَّهُ كانَ بِهِ بَصِيراً ) يرى أعماله فيجازيه عليها ولا يتركه سدى هملا.` },
            { text: "فَلَآ أُقْسِمُ بِٱلشَّفَقِ", tafsir: `أي أقسم ، أو أن « لا » للنفي كما اخترنا سابقا ( بِالشَّفَقِ ) وهي الحمرة التي تبقى في الأفق عند الغروب.` },
            { text: "وَٱلَّيْلِ وَمَا وَسَقَ", tafsir: `لا أقسم ب ( اللَّيْلِ وَما وَسَقَ ) أي ما جمع وضم مما كان منتشرا بالنهار من أقسام الحيوان ، وأفراد الإنسان ، يقال وسقه : إذا جمعه.` },
            { text: "وَٱلْقَمَرِ إِذَا ٱتَّسَقَ", tafsir: `لا أقسم ب ( الْقَمَرِ إِذَا اتَّسَقَ ) أي إذا تكامل بدرا فإنه يجتمع حينئذ ، افتعال من « وسق » .` },
            { text: "لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ", tafsir: `أي لتشاهدون ، وتعانون ( طَبَقاً ) أي حالا ( عَنْ طَبَقٍ ) أي بعد حال سابقة ، مما قدر لكم من الأحوال ، والإتيان ب « عن » لأنها فَما لَهُمْ لا يُؤْمِنُونَ (20) وَإِذا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لا يَسْجُدُونَ (21) بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ (22) وَاللهُ أَعْلَمُ بِما يُوعُونَ (23) للتجاوز ، أي تركبن حالا مجاوزين عن حال سابقة ، وإنما سمي الحال طبقا لأنه يطابق الإنسان ، والمعنى أنكم تسيرون في أحوالكم المختلفة سيرا حتى تنتهون إلى يوم القيامة ، كما قال في أول السورة « إنك كادح » وهذا هو جواب « لا أقسم » ، وكأن هذه الجمل للتنبيه على تغير أحوال الدنيا ، فلا يغتر الإنسان بحالها الحسن وينسى الآخرة حتى تفوته دنياه وآخرته. [21] وإذا كانت الدنيا معرض زوال وفناء ، وأحوالها معرض تبدل وانقلاب ( فَما لَهُمْ ) أي لهؤلاء الكفار ( لا يُؤْمِنُونَ ) بالله حتى ينجون من عذاب الآخرة الباقية ؟` },
            { text: "فَمَا لَهُمْ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ", tafsir: `ما لهم ( إِذا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لا يَسْجُدُونَ ) أي لا يخضعون لله سبحانه ، بعد أن تتلى عليهم آياته ، وتتم عليهم الحجة بقراءة القرآن عليهم ؟` },
            { text: "بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ", tafsir: `عوض أن يخضعوا ( يُكَذِّبُونَ ) بالله والرسول واليوم الآخر.` },
            { text: "وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ", tafsir: `من كل أحد حتى من أنفسهم ( بِما يُوعُونَ ) هؤلاء المكذبون ، والمعنى بما يضمرون في صدورهم من الكفر والنوايا السيئة ، من « وعي » بمعنى تقبل وجمع ، يقال « فلان يعي الكلام » أي يتقبله ويحفظه. فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ (24) إِلاَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ (25)` },
            { text: "فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ", tafsir: `يا رسول الله ، والإتيان بلفظ البشارة للاستهزاء بهم ـ بعلاقة الضد ـ ( بِعَذابٍ أَلِيمٍ ) مؤلم موجع لهم.` },
            { text: "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ", tafsir: `` }
        ]
    },
    85: { // سورة البروج
        name: "البروج",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ", tafsir: `أي قسما بالسماء التي هي صاحبة البروج ، جمع برج وهو القطعة من السماء ، سميت برجا لظهوره ، من برج : إذا ظهر ، والبروج هي الحمل والثور والجوزاء والسرطان والأسد والسنبلة والميزان والعقرب والقوس والجدي والدلو والحوت ، والقمر في سيره النفسي يقطع كل برج في ظرف يومين ونصف ، والشمس تقطعه في ظرف شهر.` },
            { text: "وَٱلْيَوْمِ ٱلْمَوْعُودِ", tafsir: `قسما ب ( الْيَوْمِ الْمَوْعُودِ ) وهو يوم القيامة ، الذي وعد به الخلق.` },
            { text: "وَشَاهِدٍ وَمَشْهُودٍ", tafsir: `قسما ب ( شاهِدٍ وَمَشْهُودٍ ) في ذلك اليوم ، أو كل شاهد ومشهود. وهذا الأقرب بالعموم ، وإن أورد في التفسير معاني مختلفة لهما.` },
            { text: "قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ", tafsir: `هو الشق العظيم في الأرض ، أي قتل الله أصحاب الأخدود الكفار الذين حفروا الأخاديد في الأرض لتعذيب المؤمنين ، وهذا دعاء على أولئك الكفار ، وكان من قصتهم على ما نقله القمي : إن الذي هيج الحبشة على غزو اليمن ذو نواس ، وهو آخر من ملك من حمير تهود واجتمعت معه حمير على اليهودية ، وسمى نفسه يوسف ، وأقام على ذلك حينا من الدهر ، ثم أخبر أن بنجران بقايا قوم على دين النصرانية وكانوا على دين عيسى وعلى حكم الإنجيل ، ورأس ذلك الدين عبد الله بن برياس ، فحمله أهل دينه على أن يسير إليهم ويحملهم على اليهودية ويدخلهم فيها فسار حتى قدم نجران ، فجمع من كان بها على دين النصرانية ، ثم عرض عليهم دين اليهودية والدخول فيه فأبوا عليه ، فجادلهم وعرض عليهم وحرص الحرص كله النَّارِ ذاتِ الْوَقُودِ (5) إِذْ هُمْ عَلَيْها قُعُودٌ (6) وَهُمْ عَلى ما يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ (7) وَما نَقَمُوا مِنْهُمْ إِلاَّ أَنْ يُؤْمِنُوا بِاللهِ الْعَزِيزِ الْحَمِيدِ (8) فأبوا عليه وامتنعوا من اليهودية والدخول فيها واختاروا القتل ، فاتخذ لهم أخدودا وجمع فيه من الحطب وأشعل فيه النار ، فمنهم من أحرق بالنار ومنهم من قتل بالسيف ومثلّ بهم كل مثلة فبلغ عدد من قتل وأحرق بالنار عشرين ألفا وأفلت رجل منهم يدعى « دوس » (1) .` },
            { text: "ٱلنَّارِ ذَاتِ ٱلْوَقُودِ", tafsir: `بدل عن أخدود أي أصحاب النار ( ذاتِ الْوَقُودِ ) الكثير ، إشارة إلى عظم تلك النار ، والوقود : هو الحطب الذي توقد به النار.` },
            { text: "إِذْ هُمْ عَلَيْهَا قُعُودٌ", tafsir: `أي أولئك الأصحاب الكفار ( عَلَيْها ) أي على حوالي النار ( قُعُودٌ ) جمع قاعد ، أي كان الكفار قاعدين أطراف النار يشاهدون ما يفعل بالمؤمنين من رميهم فيها.` },
            { text: "وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ", tafsir: `الملك الكافر وأصحابه ( عَلى ما يَفْعَلُونَ ) جلاوزتهم ( بِالْمُؤْمِنِينَ ) من إلقائهم في النار ( شُهُودٌ ) جمع شاهد ، أي حاضرون مشاهدون ، وهذا ذم لهم كيف رضوا وسمحت لهم أنفسهم بأن يشاهدوا هذا النحو من التعذيب البشع.` },
            { text: "وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ", tafsir: `أي ما كره الملك وأصحابه من المؤمنين ( إِلَّا أَنْ يُؤْمِنُوا بِاللهِ ) ويتركوا دين الملك الباطل ( الْعَزِيزِ ) الغالب في سلطانه ( الْحَمِيدِ ) المجرد في أفعاله ، إشارة إلى أن الغلب كان للمؤمنين ، ( 1) تفسير القمي : ج 2 ص 413. الَّذِي لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَاللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ (9) إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِناتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذابُ جَهَنَّمَ وَلَهُمْ عَذابُ الْحَرِيقِ (10) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ذلِكَ الْفَوْزُ الْكَبِيرُ (11) وإن صال الملك وجال أياما ، كما أن ما فعل بالمؤمنين كان لحكمة وصلاح لهم لعلو درجاتهم.` },
            { text: "ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ", tafsir: `فهو المالك المطلق لهما ( وَاللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ ) أي حاضر عالم ، فلم يغب عنه ما فعلوا بالمؤمنين فسينتقم منهم.` },
            { text: "إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ", tafsir: `أي عذبوهم وأحرقوهم بنار الأخدود ، من أصحاب ذلك الملك الطاغي ( ثُمَّ لَمْ يَتُوبُوا ) بعد ذلك بالإيمان والطاعة ( فَلَهُمْ عَذابُ جَهَنَّمَ ) في الآخرة بكفرهم ( وَلَهُمْ عَذابُ الْحَرِيقِ ) بما أحرقوا المؤمنين ، وكأن المراد بعذاب جهنم سائر أنواع عذابها من لدغ السامات وأكل الزقوم ، وشرب الغسلين وما أشبه ، و « حريق » اسم النار ، ولذا أضيف إليه « عذاب » . [12] وفي مقابل أولئك المؤمنون ( إِنَّ الَّذِينَ آمَنُوا ) بالله ورسوله واليوم الآخر ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ لَهُمْ جَنَّاتٌ ) أي بساتين ، وسميت جنة لتستر أرضها بالأشجار والقصور ( تَجْرِي مِنْ تَحْتِهَا ) أي من تحت قصورها وأشجارها ( الْأَنْهارُ ) من عسل ولبن وخمر وماء وغيرها ( ذلِكَ ) التنعم بتلك الجنات ( الْفَوْزُ ) والفلاح ( الْكَبِيرُ ) الذي ليس فوقه فوز. ولعل المراد ب ( إِنَّ الَّذِينَ فَتَنُوا ) ، و ( إِنَّ الَّذِينَ إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ (12) إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ (13) وَهُوَ الْغَفُورُ الْوَدُودُ (14) ذُو الْعَرْشِ الْمَجِيدُ (15) فَعَّالٌ لِما يُرِيدُ (16) هَلْ أَتاكَ حَدِيثُ الْجُنُودِ (17) آمَنُوا ) ، مطلق الكفار والمؤمنين ، لا خصوص الكافر والمؤمن من أصحاب الأخدود ، أو أصحاب الرسول ومعاصريه.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ", tafsir: `` },
            { text: "إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ", tafsir: `يا رسول الله ، أي أخذه للكافرين وانتقامه منهم ( لَشَدِيدٌ ) فانه إذا بطش بأحد يغشاه العذاب ، بمختلف ألوانه وصنوفه ، فليحذر الكفار والعصاة بطشه.` },
            { text: "إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ", tafsir: `سبحانه ( هُوَ يُبْدِئُ ) الخلق ، بأن يعطيهم الحياة من العدم أولا ( وَيُعِيدُ ) للخلق بعد الممات أحياء.` },
            { text: "وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ", tafsir: `لمن تاب وآمن ، أي كثير المغفرة ( الْوَدُودُ ) الذي يحب الناس فلا يريد تعذيبهم إلا إذا تمادوا في الكفر والعصيان.` },
            { text: "ذُو ٱلْعَرْشِ ٱلْمَجِيدُ", tafsir: `وهو كناية عن أن له الملك ، يقال للملك « صاحب العرش » كناية عن سلطانه ، وإن لم يكن له كرسي يجلس عليه ( الْمَجِيدُ ) الموصوف بالمجد والعظمة.` },
            { text: "فَعَّالٌ لِّمَا يُرِيدُ", tafsir: `أي كثير الفعل ( لِما يُرِيدُ ) فكل شيء أراده فعله لا يمتنع عليه شيء ، وهذه الآيات للإلماع إلى وجوب رجاء البشر إياه ، وخوفهم منه ، لأن له الملك والعظمة وأنه يفعل ما يشاء فعله. [18] ثم جاء السياق لبيان شاهد على ما تقدم من أنه سبحانه يفعل ما يريد ، ليرجوه المؤمن ويخافه الكافر ( هَلْ أَتاكَ ) يا رسول الله أو أيها السامع ( حَدِيثُ الْجُنُودِ ) أي هل بلغك خبر الذين تجندوا على خلاف الله فِرْعَوْنَ وَثَمُودَ (18) بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ (19) وَاللهُ مِنْ وَرائِهِمْ مُحِيطٌ (20) بَلْ هُوَ قُرْآنٌ مَجِيدٌ (21) فِي ل َوْحٍ مَحْفُوظٍ (22) ومحاربة أنبيائه ، لتعرف كيف صنع الله بهم ؟` },
            { text: "هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ", tafsir: `` },
            { text: "فِرْعَوْنَ وَثَمُودَ", tafsir: `وجنده ، الذين أرسل إليهم موسى عليه‌السلام ( وَثَمُودَ ) الذين أرسل إليهم صالح عليه‌السلام ، فإنهم لما كذبوا الأنبياء عذبهم الله سبحانه ، وهكذا عادة الله سبحانه مع المكذبين. [20] إن كفار مكة لا يرعوون عن كفرهم وعصيانهم بهذه الأمثال والقصص ( بَلِ الَّذِينَ كَفَرُوا ) بالله ورسوله ( فِي تَكْذِيبٍ ) للإسلام والقرآن ، أي مشغولون عنه ، ومعرضون عن الحق.` },
            { text: "بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ", tafsir: `` },
            { text: "وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ", tafsir: `أي من جوانبهم ( مُحِيطٌ ) كأنهم في دائرة علم الله سبحانه الشامل ، وقدرته الواسعة فيعلم ماذا يصنعون ، وهم في قبضة قدرته ، يقول الملك « أنا محيط بفلان » يريد إحاطة علمه وقدرته لا إحاطة الجسم. [22] وليس كما ذكر الكفار إن القرآن شعر أو كهانة أو ما أشبه ( بَلْ هُوَ قُرْآنٌ مَجِيدٌ ) ، ذو مجد وعظمة لأنه من قبله سبحانه.` },
            { text: "بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ", tafsir: `` },
            { text: "فِى لَوْحٍ مَّحْفُوظٍۭ", tafsir: `` }
        ]
    },
    86: { // سورة الطارق
        name: "الطارق",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلسَّمَآءِ وَٱلطَّارِقِ", tafsir: `أي قسما بالسماء ( وَالطَّارِقِ ) أي قسما بالطارق وهو الذي يأتي ليلا ، سمي طارقا لأنه يطرق الباب ، أما في النهار فقد كانت العادة الجارية لديهم أن تفتح الأبواب ، فإذا جاء أحد استأذن ودخل ، والمراد به هنا النجم الذي يطلع ليلا.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ", tafsir: `أيها الإنسان ، أو أيها الرسول ( ما ) هو ( الطَّارِقُ ) ؟ وذلك لتعظيم شأنه. [4] هو ( النَّجْمُ الثَّاقِبُ ) الذي يثقب السماوات بنوره ، ومن يعرف عظم النجوم وكثرة بعدها حتى أنها تحتاج إلى سنوات ضوئية حتى توصل نورها إلى الأرض يعرف عظم هذا القسم. والظاهر أن المراد بالنجم الجنس لا خصوص نجم واحد ، وما ذكر له في التفسير من المصداق فهو من باب المثال.` },
            { text: "ٱلنَّجْمُ ٱلثَّاقِبُ", tafsir: `` },
            { text: "إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ", tafsir: `أي ما كل إنسان ( لَمَّا عَلَيْها حافِظٌ ) أي إلّا عليها حافظ من قبل الله سبحانه ، وهم الملائكة الذين يحفظون البشر من المهالك كما يحفظون أعمالهم ، وهذا هو متعلق القسم. [6] وإذا كان الإنسان في شكّ من الإله فليفكر في أصله ونشأته ( فَلْيَنْظُرِ الْإِنْسانُ ) أي ليفكر ويتدبر ( مِمَّ خُلِقَ ) أي مما ذا خلق ؟ وما هو أصله ؟` },
            { text: "فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ", tafsir: `` },
            { text: "خُلِقَ مِن مَّآءٍ دَافِقٍ", tafsir: `أي ماء يدفق ، والدفق هو الصب الذي فيه دفع وقوة ، فإن المني يخرج هكذا. يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرائِبِ (7) إِنَّهُ عَلى رَجْعِهِ لَقادِرٌ (8) يَوْمَ تُبْلَى السَّرائِرُ (9) فَما لَهُ مِنْ قُوَّةٍ وَلا ناصِرٍ (10) وَالسَّماءِ ذاتِ الرَّجْعِ (11) وَالْأَرْضِ ذاتِ الصَّدْعِ (12)` },
            { text: "يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ", tafsir: `ذلك الماء الذي هو مبدأ الإنسان ( مِنْ بَيْنِ الصُّلْبِ ) للرجل ، وهو العظم الذي في ظهره مركز المني ( وَالتَّرائِبِ ) نواحي الصدر ، واحدتها تريبة ، فإن مني المرأة مركزه هناك. [9] إن الله خلق الإنسان بهذه الكيفية ( إِنَّهُ عَلى رَجْعِهِ ) أي إرجاعه إلى الحياة بعد الموت ( لَقادِرٌ ) كما قدر على ابتداء خلقه حين لم يكن شيئا مذكورا. [10] قادر على رجعه في ( يَوْمَ تُبْلَى السَّرائِرُ ) أي تختبر الضمائر ، فإن « سرائر » جمع سريره ، وهي المحل الكامن في الإنسان ، فإن يوم القيامة تظهر بواطن الناس وما انطووا عليه من خير وشر.` },
            { text: "إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ", tafsir: `` },
            { text: "يَوْمَ تُبْلَى ٱلسَّرَآئِرُ", tafsir: `` },
            { text: "فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ", tafsir: `أي للإنسان ( مِنْ قُوَّةٍ ) يدفع بها العذاب ( وَلا ناصِرٍ ) ينصره من تلك الأهوال ، فليخش وليحذر أن يخالف الله سبحانه حتى لا يبتلي بالعذاب.` },
            { text: "وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ", tafsir: `أي قسما بالسماء ( ذاتِ الرَّجْعِ ) ، التي ترجع في كل دورة إلى مكانها الأول ، أو ذات المطر ، وسمي المطر رجعا لأنه يرجع كل نفسه ، أو لأنه يرجع إلى الأرض بعد التصاعد منها بالأبخرة.` },
            { text: "وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ", tafsir: `أي قسما بالأرض ( ذاتِ الصَّدْعِ ) التي تتصدع وتتشقق فيخرج منها النبات. إِنَّهُ لَقَوْلٌ فَصْلٌ (13) وَما هُوَ بِالْهَزْلِ (14) إِنَّهُمْ يَكِيدُونَ كَيْداً (15) وَأَكِيدُ كَيْداً (16) فَمَهِّلِ الْكافِرِ ينَ أَمْهِلْهُمْ رُوَيْداً (17)` },
            { text: "إِنَّهُۥ لَقَوْلٌ فَصْلٌ", tafsir: `أي القرآن ، أو ما ذكره من رجوع الخلق بعد الموت وتشقق الأرض عنهم ، وهذا هو المناسب للآيتين السابقتين ( لَقَوْلٌ فَصْلٌ ) يفصل بين الحق والباطل.` },
            { text: "وَمَا هُوَ بِٱلْهَزْلِ", tafsir: `أي اللعب ، فإنه كلام واقعي لا أنه قيل على وجه اللعب والهزل.` },
            { text: "إِنَّهُمْ يَكِيدُونَ كَيْدًا", tafsir: `أي الكفار ( يَكِيدُونَ ) ويحتالون لإبطال هذا الكلام الذي هو قول فصل ( كَيْداً ) بقولهم إنه شعر وسحر وكهانة وما أشبه ذلك.` },
            { text: "وَأَكِيدُ كَيْدًا", tafsir: `أي أريد أمرا آخر ضد ما يريدون ، وسمي كيدا للمشابهة ( كَيْداً ) كما أنهم يكيدون.` },
            { text: "فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا", tafsir: `` }
        ]
    },
    87: { // سورة الأعلى
        name: "الأعلى",
        basmalaTafsir: ``,
        verses: [
            { text: "سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى", tafsir: `أي نزّه يا رسول الله ، أو أيها المخاطب ( اسْمَ رَبِّكَ ) عما لا يليق به من الشرك والولد ، فلا تنسب إليه شيئا ينافي مقام الألوهية وذكر « اسم » للتعظيم ، فمن يجب أن يسبح اسمه يجب أن يسبح هو بالأولى ( الْأَعْلَى ) أي الأرفع من كل شيء ، فلا شيء أرفع منه في العلم أو القدرة أو الخلق أو الرزق أو غير ذلك من سائر صفات الذات وصفات الفعل.` },
            { text: "ٱلَّذِى خَلَقَ فَسَوَّىٰ", tafsir: `الخلق كلهم ( فَسَوَّى ) بينهم في الإحكام والإتقان والدقة ، فليس بعض الخلق متقنا وبعضه غير متقن ، كما سوّى خلق كل شيء فأعطاه ما يصل به إلى الكمال اللائق به من الأجهزة والآلات.` },
            { text: "وَٱلَّذِى قَدَّرَ فَهَدَىٰ", tafsir: `والتقدير هو التخطيط ، كما يقدر المهندس البناء ثم يبنيه ( فَهَدى ) كل ذي روح إلى مصالحه ، فهو خلق ، وإعطاء أجهزة ، وتقدير للحياة ، وهداية.` },
            { text: "وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ", tafsir: `أي أنبت الحشيش الذي ترعاه الحيوانات من الأرض.` },
            { text: "فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ", tafsir: `أي المرعى بعد الخضرة ( غُثاءً ) أي هشيما جافا كالغثاء الذي تراه فوق السيل ، بمعنى المجتمع من هنا وهناك بلا علاقة وارتباط ومشابهة ( أَحْوى ) أي أسود بعد الخضرة ، فإن الحوة بمعنى السواد. سَنُقْرِئُكَ فَلا تَنْسى (6) إِلاَّ ما شاءَ اللهُ إِنَّهُ يَعْلَمُ الْجَهْرَ وَما يَخْفى (7) وَنُيَسّ ِرُكَ لِلْيُسْرى (8) [7] ومن هدايته سبحانه أنه أنزل القرآن على الرسول ، و قد قال ابن عباس : كان النبي صلى‌الله‌عليه‌وآله‌وسلم إذا أنزل عليه جبرئيل بالوحي يقرأه مخافة أن ينساه ، فكان لا يفرغ جبرئيل من آخر الوحي حتى يشرع الرسول في القراءة. فأنزل الله تعالى عليه هذه الآية (1) ( سَنُقْرِئُكَ ) القرآن ، أي نتلو عليك لتقرأه ( فَلا تَنْسى ) منه شيئا ، فقد شاءت إرادته سبحانه أن يكون النبي صلى‌الله‌عليه‌وآله‌وسلم منزّها عن النسيان ، وكذلك سائر الأنبياء عليهم‌السلام . أما قوله « تنسى » فهو من قبيل ( إِنَّا نَسِيناكُمْ ) (2) ، ولعل العمل كان تعليما للمسلمين فيما بعد بأن يحرصوا على القرآن مثل هذا الحرص.` },
            { text: "سَنُقْرِئُكَ فَلَا تَنسَىٰٓ", tafsir: `` },
            { text: "إِلَّا مَا شَآءَ ٱللَّهُ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ", tafsir: `أن تنساه ، وفيه دلالة على أن عدم نسيانه إنما هو من الله سبحانه ، حتى أنه إذا شاء غيره قدر عليه ، قالوا : ودخول المشيئة في هذه الآية للدلالة على أن النبي مهما بلغ من العظمة فإن جميع أموره بيده تعالى ( إِنَّهُ ) سبحانه ( يَعْلَمُ الْجَهْرَ ) من الكلام ( وَما يَخْفى ) كالسر والنجوى ، فكل ذلك من الإقراء وعدم النسيان إلا بمشيئته تابع لعلمه الواسع الذي يشمل كل شيء ، وبما علّمه من الصلاح جعل النبي صلى‌الله‌عليه‌وآله‌وسلم بحيث لا ينسى ، وإلا فلو كان ينسى لم يؤمن على التبليغ ، لتطرق احتمال النسيان في كل شيء من أقواله وأفعاله.` },
            { text: "وَنُيَسِّرُكَ لِلْيُسْرَىٰ", tafsir: `يا رسول الله ، أي نوفقك ( لِلْيُسْرى ) أي الطريقة اليسرى ( 1) مجمع البيان : ج 10 ص 329. ( 2) السجدة : 15. فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرى (9) سَيَذَّكَّرُ مَنْ يَخْشى (10) وَيَتَجَنَّبُهَا الْأَشْقَى (11) الَّذِي يَصْلَى النَّارَ الْكُبْرى (12) ثُمَّ لا يَمُوتُ فِيها وَلا يَحْيى (13) قَدْ أَفْلَحَ مَنْ تَزَكَّى (14) في جميع الأمور ، فإن أحكامه سبحانه توصل إلى السعادة بأيسر الطرق وأسهلها.` },
            { text: "فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ", tafsir: `يا رسول الله الناس بما أودع فيهم من الفطرة الدالة على الألوهية والمعاد وما أشبه ( إِنْ نَفَعَتِ الذِّكْرى ) أي إن كان الذكر في معرض النفع ولو إتمام الحجة ، أما إذا علم الرسول أن ذكره لا ينفع إطلاقا في الهداية لليأس ، ولا في إتمام الحجة لتمام الحجة على المخاطبين سابقا ، فلا لزوم للتذكير. وقيل « إن » بمعنى « قد » أي قد نفعت الذكرى ، بمعنى قد تنفع.` },
            { text: "سَيَذَّكَّرُ مَن يَخْشَىٰ", tafsir: `أصله « يتذكر » أدغمت التاء في الذال وجيء بهمزة الوصل لتعذر الابتداء بالساكن ( مَنْ يَخْشى ) أي سيتعظ بالقرآن وبكلامك من يخشى عقاب الله سبحانه.` },
            { text: "وَيَتَجَنَّبُهَا ٱلْأَشْقَى", tafsir: `أي يبتعد عن الموعظة والذكرى ( الْأَشْقَى ) أي الأكثر شقوة ، فإن الكافر المجتنب للذكرى أكثر شقاء من العاصي.` },
            { text: "ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ", tafsir: `أي يدخل ويلازم ( النَّارَ الْكُبْرى ) وهي نار جهنم.` },
            { text: "ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ", tafsir: `أي في تلك النار ليستريح ( وَلا يَحْيى ) حياة هادئة مريحة.` },
            { text: "قَدْ أَفْلَحَ مَن تَزَكَّىٰ", tafsir: `أي فاز ونجح ( مَنْ تَزَكَّى ) أي تطهر باجتناب الرذائل ، والتحلي بالفضائل. وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى (15) بَلْ تُؤْثِرُونَ الْحَياةَ الدُّنْيا (16) وَالْآخِرَةُ خَيْرٌ وَأَبْقى (17) إِنَّ هذا لَفِي الصُّحُفِ الْأُولى (18) صُحُفِ إِبْراهِيمَ وَمُوسى (19)` },
            { text: "وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ", tafsir: `أي تذكر الله سبحانه بقلبه ، والإتيان ب « اسم » للتعظيم ( فَصَلَّى ) لله ، أي خضع وخشع ، أو أتى بالصلاة فإنها دليل خشوع الإنسان وتذكره لله تعالى. وفي بعض الروايات أن المراد بها زكاة الفطرة وصلاة العيد ، والظاهر أنها من باب المصداق ، وانطباق الكلي على مصاديقه يمكن أن يكون بعد مدة ـ عند وجود المصداق فلا يقال : كيف يصح والسورة مكية ولم يكن هناك زكاة فطرة ولا صلاة عيد ؟` },
            { text: "بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا", tafsir: `أنتم أيها الناس لا تفعلون ذلك ، وإنما ( تُؤْثِرُونَ ) أي تختارون ( الْحَياةَ الدُّنْيا ) أي الحياة القريبة ، تختارونها على الآخرة فتصرفون أموالكم وأوقاتكم في ملاذّها ، لا في الزكاة والصلاة.` },
            { text: "وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ", tafsir: `أي الجنة ( خَيْرٌ ) من الدنيا ، لأن نعيمها أكثر ولا يشوبها كدر ( وَأَبْقى ) لأنها دائمة مستمرة ، بخلاف الدنيا فإنها فانية زائلة.` },
            { text: "إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ", tafsir: `الذي ذكر من فلاح المتزكي المصلي ، أو سائر ما ذكر في هذه السورة ( لَفِي الصُّحُفِ الْأُولى ) فكل كتب الله المنزلة تحرض على الزكاة والصلاة وسائر الخيرات ، وليس هذا بدعا من القرآن.` },
            { text: "صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ", tafsir: `` }
        ]
    },
    88: { // سورة الغاشية
        name: "الغاشية",
        basmalaTafsir: ``,
        verses: [
            { text: "هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ", tafsir: `أيها الإنسان ، أو يا رسول الله ( حَدِيثُ الْغاشِيَةِ ) أي خبر القيامة ؟ وتسمى بالغاشية لأنها تغشى الناس بأهوالها ، والاستفهام للإلفات والإيقاظ.` },
            { text: "وُجُوهٌ يَوْمَئِذٍ خَٰشِعَةٌ", tafsir: `أي في يوم القيامة ( خاشِعَةٌ ) ذليلة بسبب ما عملت من الكفر والآثام ، وإنما نسب الخشوع إلى الوجوه لظهوره فيها.` },
            { text: "عَامِلَةٌ نَّاصِبَةٌ", tafsir: `قد عملت في النار وكدت ( ناصِبَةٌ ) وتعبت ، فإن النصب بمعنى التعب ، ولكنها لم تنتفع بأعمالها وأتعابها ، بل بالعكس صارت دنياه سببا للعذاب والعقاب.` },
            { text: "تَصْلَىٰ نَارًا حَامِيَةً", tafsir: `أي تدخل تلك الوجوه النار وتلازمها ( حامِيَةً ) قد حميت حتى تناهت في الحرّ.` },
            { text: "تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ", tafsir: `أي أصحاب تلك الوجوه ، وقد أطلق الوجوه على أصحابها بعلاقة الجزء والكل ، من قبيل إطلاق « الرقبة » على الإنسان ( مِنْ عَيْنٍ آنِيَةٍ ) قد بلغت حرارتها وأناها إلى منتهى الدرجة ، فإن آنية بمعنى البالغة أشد درجات الحرارة. [7] ذاك شرابهم ، فما هو طعامهم ؟ ( لَيْسَ لَهُمْ طَعامٌ إِلَّا مِنْ ضَرِيعٍ ) وهو نبت يضر ولا ينفع. و في حديث عن النبي صلى‌الله‌عليه‌وآله‌وسلم إنه شيء يكون في النار يشبه الشوك أمرّ من الصبر وأنتن من الجيفة وأشد حرّا من النار (1) . ( 1) مجمع البيان : ج 10 ص 336. لا يُسْمِنُ وَلا يُغْنِي مِنْ جُوعٍ (7) وُجُوهٌ يَوْمَئِذٍ ناعِمَةٌ (8) لِسَعْيِها راضِيَةٌ (9) فِي جَنَّةٍ عالِيَةٍ (10) لا تَسْمَعُ فِيها لاغِيَةً (11) فِيها عَيْنٌ جارِيَةٌ (12) فِيها سُرُرٌ مَرْفُوعَةٌ ( 13) وَأَكْوابٌ مَوْضُوعَةٌ (14)` },
            { text: "لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ", tafsir: `` },
            { text: "لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ", tafsir: `أكله ( وَلا يُغْنِي مِنْ جُوعٍ ) فآكله يحس بالجوع بعد أكله كما يحس بالجوع قبل أكله. [9] ذلك أحوال العصاة فلننظر إلى أحوال المتقين ( وُجُوهٌ يَوْمَئِذٍ ) أي في يوم القيامة ( ناعِمَةٌ ) منعمة في أنواع اللذات ظاهر عليها أثر النعمة والسرور.` },
            { text: "وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ", tafsir: `` },
            { text: "لِّسَعْيِهَا رَاضِيَةٌ", tafsir: `في الدنيا وما عملت سابقا ( راضِيَةٌ ) حيث قد حصلت على الجنة بسببها.` },
            { text: "فِى جَنَّةٍ عَالِيَةٍ", tafsir: `رفيعة المكان والقدر ، فإن قصورها ومكانها في أعالي الجو.` },
            { text: "لَّا تَسْمَعُ فِيهَا لَٰغِيَةً", tafsir: `أولئك الأشخاص أصحاب الوجوه الناعمة ( فِيها ) في الجنة ( لاغِيَةً ) أي كلمة ساقطة لا فائدة فيها.` },
            { text: "فِيهَا عَيْنٌ جَارِيَةٌ", tafsir: `أي في تلك الجنة ( عَيْنٌ جارِيَةٌ ) تجري حتى يتناول الماء كل إنسان يمر بها ، والماء الجاري أطيب ذوقا وأجمل في النظر.` },
            { text: "فِيهَا سُرُرٌ مَّرْفُوعَةٌ", tafsir: `أي في تلك الجنة ( سُرُرٌ ) جمع سرير ، وهو الكرسي ( مَرْفُوعَةٌ ) في المكان ، وفي القيمة ، وفي القدر.` },
            { text: "وَأَكْوَابٌ مَّوْضُوعَةٌ", tafsir: `جمع كوب ، وهو قدح صغير جميل ( مَوْضُوعَةٌ ) على حافات الأنهر للاستقاء والشرب ، وفي تقابل « موضوعة » ل « مرفوعة » وَنَمارِقُ مَصْفُوفَةٌ (15) وَزَرابِيُّ مَبْثُوثَةٌ (16) أَ فَلا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ (17) وَإِلَى السَّماءِ كَيْفَ رُفِعَتْ (18) وَإِلَى الْجِبالِ كَيْفَ نُصِبَتْ (19) بلاغة بديعة.` },
            { text: "وَنَمَارِقُ مَصْفُوفَةٌ", tafsir: `جمع نمرقة ، وهي الوسادة التي يتكأ عليها ( مَصْفُوفَةٌ ) قد صف بعضها إلى جانب البعض.` },
            { text: "وَزَرَابِىُّ مَبْثُوثَةٌ", tafsir: `جمع زربي ، وهو البساط ( مَبْثُوثَةٌ ) أي منتشرة مفروشة للجلوس عليها. [18] وإذ ذكر سبحانه بعض أحوال الجنة والنار عطف السياق نحو الأدلة الدالة على الألوهية ، تعبئة للناس نحو السعادة الأبدية ( أَ فَلا يَنْظُرُونَ ) هؤلاء المنكرون للخالق ( إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ ) في إحكام وتدقيق ، وليس لأي حيوان بالذات خصوصية ، في التذكير بالله سبحانه والدلالة عليه ، إذ كل حيوان آية دالة على وجود الله وسائر صفاته ، وإنما ذكر الإبل لأنها إحدى الآيات الأليفة للعرب ، مع مناسبة لها بسائر ما ذكر في الآيات التالية فإن السماء المرفوعة والأرض المسطوحة الوسيعة والجبال المرفوعة إنما تلائمها الإبل السائرة عبر الصحاري حيث لا شيء إلا الأرض والجبال والسماء.` },
            { text: "أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ", tafsir: `` },
            { text: "وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ", tafsir: `؟ والمراد بها الكواكب ، أو المدارات ، أو ما يرى من الهواء الملون.` },
            { text: "وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ", tafsir: `على الأرض كالأوتاد لئلّا تزول وتتحرك وتضطرب ؟. وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ (20) فَذَكِّرْ إِنَّما أَنْتَ مُذَكِّرٌ (21) لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ (22) إِلاَّ مَنْ تَوَلَّى وَكَفَرَ (23) فَيُعَذِّبُهُ اللهُ الْعَذابَ الْأَكْبَرَ (24) إِنَّ إِلَيْنا إِيابَهُمْ (25) ثُمَّ إِنَّ عَلَيْنا حِسابَهُمْ (26)` },
            { text: "وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ", tafsir: `؟ أي بسطت لتصلح طرائق للناس ، والمراد أ فلا يتفكرون في هذه المخلوقات حتى يستدلوا بها على وجوده سبحانه وسائر صفاته ؟ والاستفهام للتوبيخ والتقريع.` },
            { text: "فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ", tafsir: `يا رسول الله الناس بهذه الآيات ( إِنَّما أَنْتَ مُذَكِّرٌ ) تبين لهم الحقائق ليتذكروا ما أودع في فطرتهم من الألوهية والمعاد وما أشبه.` },
            { text: "لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ", tafsir: `أي على هؤلاء القوم ( بِمُصَيْطِرٍ ) أي بمسلط ، حتى تكون مسئولا عن انحرافهم ، وإنما شأن الأنبياء التذكير والوعظ ، فمن شاء اهتدى ومن شاء انحرف.` },
            { text: "إِلَّا مَن تَوَلَّىٰ وَكَفَرَ", tafsir: `، فإن الذكرى تنفع ( إِلَّا ) في ( مَنْ تَوَلَّى ) أي من أعرض عن الحق ( وَكَفَرَ ) بالله واليوم الآخر ، وذلك لا يفلت من قبضة الله سبحانه.` },
            { text: "فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ", tafsir: `وهو عذاب الآخرة.` },
            { text: "إِنَّ إِلَيْنَآ إِيَابَهُمْ", tafsir: `أي إلى جزائنا وحسابنا ( إِيابَهُمْ ) أي رجوعهم بعد الموت ، من « آب » بمعنى رجع.` },
            { text: "ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم", tafsir: `` }
        ]
    },
    89: { // سورة الفجر
        name: "الفجر",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلْفَجْرِ", tafsir: `أي قسما بالفجر ، وهو انفجار الصبح قبل طلوع الشمس ، فإن النور يظهر ممتدا في جانب المشرق قبل ساعة ونصف من الطلوع.` },
            { text: "وَلَيَالٍ عَشْرٍ", tafsir: `أي قسما بالليالي العشر من ذي الحجة ـ على ما ذكروا ـ وكأن الحلف هنا بما ينشأ منه الخير ، فإن الفجر ينشأ منه الضياء ، وهذه الليالي محل الأعمال والطاعات.` },
            { text: "وَٱلشَّفْعِ وَٱلْوَتْرِ", tafsir: `قسما ب ( الشَّفْعِ ) ركعتا صلاة الليل ( وَالْوَتْرِ ) الركعة الأخيرة منها ، أو الشفع يوم تروية ، والوتر يوم عرفة ـ كما روي ـ .` },
            { text: "وَٱلَّيْلِ إِذَا يَسْرِ", tafsir: `قسما ب ( اللَّيْلِ إِذا يَسْرِ ) أي يمضي ، كقوله : ( وَاللَّيْلِ إِذْ أَدْبَرَ ) (1) وأصله « يسري » حذف الياء للسياق ، والمقسم له محذوف ، تقديره لنعاقب الكفار ، دلّ عليه قوله « ألم تر .. » .` },
            { text: "هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ", tafsir: `الذي تقدم من الأيمان ( قَسَمٌ ) يكن ( لِذِي حِجْرٍ ) أي ذي عقل ؟ فإن « الحجر » من أسماء العقل ، سمي بذلك لأنه يحجر صاحبه عن الإتيان بما لا يليق به ، والاستفهام للتأنيب ، بمعنى كيف لا تصدقون بما نقول بعد هذه الأيمان ؟.` },
            { text: "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ", tafsir: `يا رسول الله ، أو أيها السامع ، والمراد بالرؤية العلم ، أي ألم تعلم ( كَيْفَ فَعَلَ رَبُّكَ بِعادٍ ) أي بقبيلة عاد ؟` },
            { text: "إِرَمَ ذَاتِ ٱلْعِمَادِ", tafsir: `عطف بيان ل « عاد » ، وهي اسم أرض بنت عاد عليها أبنية فخمة ( 1) المدثر : 34. ذاتِ الْعِمادِ (7) الَّتِي لَمْ يُخْلَقْ مِثْلُها فِي الْبِلادِ (8) وَثَمُودَ الَّذِينَ جابُوا الصَّخْرَ بِالْوادِ (9) وَفِرْعَوْنَ ذِي ا لْأَوْتادِ (10) جميلة ، وإنما مع أن تكون « إرم » عطف بيان ، لأن « عادا » اسم لقبيلتين « عاد » الأولى و « عاد » الثانية ، فالأولى كانت صاحبة « إرم » والتقدير « عاد إرم » ، وهذا كما تقول « مررت ببني هاشم ، المدينة المنورة » ( ذاتِ الْعِمادِ ) جمعه عمد ، أي أبنية إرم التي كانت لها أعمدة ، ويستعمل العماد في القوة والشرف ، يقال « فلان رفيع العماد » . فقد قالوا إن « شداد » من أبناء « عاد » توسع سلطانه ، وعظم أمره ، وكان كافرا بالله ، فسمع بالجنة وأوصافها ، فقال نبني في الأرض مثلها ، فبناها في « إرم » وسميت بهذا الاسم ، وكانت عظيمة فخمة جميلة ذات قصور وحدائق وأثاث ورياش ، فلما أن أراد هو وقومه وجيشه دخولها أهلكهم الله سبحانه ، بأن بعث عليهم صيحة عظيمة فهلكوا جميعا.` },
            { text: "ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ", tafsir: `أي مثل قبيلة عاد ـ في القوة والثروة وما أشبه ـ أو مثل « إرم » في الفخامة والضخامة والجمال ( فِي الْبِلادِ ) والظاهر أن المراد عدم خلق مثلها في تلك الأزمنة ، لا مطلقا.` },
            { text: "وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ", tafsir: `ألم تر كيف فعل ربك ب ( ثَمُودَ ) قوم صالح ( الَّذِينَ جابُوا الصَّخْرَ ) أي قطعوا الصخور من الجبال ، وجاؤوا بها ( بِالْوادِ ) أي وادي قرى ، وهو مسكنهم فبنوا بها البيوت الصخرية ؟` },
            { text: "وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ", tafsir: `ألم تر كيف فعل ربك ب ( فِرْعَوْنَ ذِي الْأَوْتادِ ) جمع « وتد » الذي كان يدق في جسم مخالفيه الوتد ، ويذره حتى يموت ـ كما قيل ـ الَّذِينَ طَغَوْا فِي الْبِلادِ (11) فَأَكْثَرُوا فِيهَا الْفَسادَ (12) فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذابٍ (13) إِنَّ رَبَّكَ لَبِالْمِرْصادِ (14) فَأَمَّا الْإِنْ سانُ إِذا مَا ابْتَلاهُ رَبُّهُ والمراد به فرعون موسى عليه‌السلام وقد مثل الله سبحانه بأقوى الأمم في زمانهم ، ليبين أنهم حيث عتوا وخالفوا أوامر الله سبحانه أهلكهم سبحانه ولم تنفعهم قوتهم شيئا ومصير هؤلاء الكفار ـ الذين هم أضعف من أولئك ـ مصير أولئك لو تمادوا في الكفر والطغيان.` },
            { text: "ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ", tafsir: `أي تجبروا على أنبياء الله ، وعملوا بالكفر والمعاصي.` },
            { text: "فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ", tafsir: `أي في البلاد ( الْفَسادَ ) بالقتل والفجور وغيرهما.` },
            { text: "فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ", tafsir: `وإنما عبر عن العذاب بالسوط لشدة إيلامه ، ونسب إليه الصب لأن السوط حيث فيه لين يأتي إلى الجسم تدريجيا مشابها للصب ، الذي يأتي على الجسم بتدريج ـ وفي هذا التعبير من البلاغة ما لا يخفى ـ .` },
            { text: "إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ", tafsir: `يا رسول الله ( لَبِالْمِرْصادِ ) هو المحل الذي يجلس الإنسان ليرصد ويراقب أحوال غيره ـ من حيث لا يرونه ـ وهذا كناية عن أنه سبحانه مطلع على الناس ، فمن كفر وأساء مراقب من قبله تعالى ، لا يفوته. [16] وهكذا يطغي الإنسان ـ ليكون له ذلك المصير ـ إذا لم يسترشد بإرشادات الله تعالى ( فَأَمَّا الْإِنْسانُ ) والمراد به الذي لم يهتد بنور الإيمان ( إِذا مَا ابْتَلاهُ رَبُّهُ ) أي امتحنه واختبره ، و « ما » مزيدة جيئت فَأَكْرَمَهُ وَنَعَّمَهُ ف َيَقُولُ رَبِّي أَكْرَمَنِ (15) وَأَمَّا إِذا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهانَنِ (16) كَلاَّ بَلْ لا تُكْرِمُونَ للتأكيد ، ولعل النكتة في زيادتها الإلماع إلى أن « ابتلاءه » ليس بابتلاء حقيقة ، وإنما هو شيء طفيف يصيبه ومع ذلك لا ينجح في الامتحان ( فَأَكْرَمَهُ وَنَعَّمَهُ ) بأن جعل له مكانا كريما ذا شرافة ، ونعمة وافرة ، ليختبره هل يعمل بوظيفته في الثروة والجاه أم لا ؟ فيفرح بذلك ويظنه ثوابا له وجزاء على عمله ، وأنه باستحقاق أوتي ما أوتي ويقول ( رَبِّي أَكْرَمَنِ ) حذفت الياء تخفيفا ، أي أن هذا لكرامتي على الله ، ولا يعتبره امتحانا.` },
            { text: "فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ", tafsir: `` },
            { text: "وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ", tafsir: `أي امتحنه الله سبحانه بالفقر والضعة ( فَقَدَرَ ) أي ضيق ( عَلَيْهِ ) أي على الإنسان ( رِزْقَهُ ) فجعله فقيرا مملقا فيحزن لذلك ويظن أن ذلك هوان من الله عليه ، ويقول ( رَبِّي أَهانَنِ ) أي أهانني ، ولا يعتبر ذلك ابتلاء ، وهذا بخلاف الإنسان المؤمن الذي يرى كل شيء يصيبه اختبارا وامتحانا ، فيخاف من النعمة لئلا يعصي الله فيها فلا يشكره ، ولا يحزن من الفقر لأنه يعتبره امتحانا له إن صبر كان رفعا لدرجته.` },
            { text: "كَلَّا بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ", tafsir: `ليس الأمر كما ظن هذا الإنسان ، فإن التنعيم ليس لكرامة ، والإفقار ليس لإهانة بل كل ذلك مختلف ، والمجموع للابتلاء والاختبار ( بَلْ ) إنهم غافلون عن حكمة الإعطاء والمنع ، ذاهلون أن كل ذلك للابتلاء ، ولذا لا يقومون بواجب العطاء ـ ولم يذكر القيام بواجب الفقر من الصبر ، لأن الكلام كان موجها نحو الأغنياء من الناس الذين مثل لهم بمصارع عاد وثمود وفرعون ـ ف ـ ( لا تُكْرِمُونَ الْيَتِيمَ (17) وَلا تَحَاضُّونَ عَلى طَعامِ الْمِسْكِينِ (18) وَتَأْكُلُونَ التُّراثَ أَكْلاً لَمًّا (19) وَتُحِبُّونَ الْمالَ حُبًّا جَمًّا (20) كَلاَّ إِذا دُكَّ تِ الْأَرْضُ دَكًّا دَكًّا (21) الْيَتِيمَ ) الذي مات أبواه ، بإيوائه وإعطائه.` },
            { text: "وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ", tafsir: `من الحض ـ وهو الحث ـ أي لا يحث بعضكم بعضا ( عَلى طَعامِ الْمِسْكِينِ ) أي الفقير الذي أسكنه فقره عن الحركة في الأمور.` },
            { text: "وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا", tafsir: `أي الميراث ( أَكْلاً لَمًّا ) شديدا تلمون جميعه في الأكل ، بلا إعطاء حقوق الميت ، وحقوق الله ، وحقوق سائر ذوي الميراث ، فإنهم كانوا يحرمون النساء والصبيان والضعفاء من الورثة ، فلا يعطونهم من حقهم شيئا ، وهذا دليل الشرة نحو المال وإنهم لا يجعلون المال دليلا للابتلاء ، بل دليلا لتكريم الله لهم.` },
            { text: "وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا", tafsir: `أي حبا كثيرا شديدا ، حتى أنهم لا ينفقونه فيما يجب أو يستحب إنفاقه ، كما هو شأن من لا يؤمن بالله واليوم الآخر ، ولا يجعل المال دليل الابتلاء ليعمل فيه بأمر الله ويخشى مغبته.` },
            { text: "كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا", tafsir: `ليس الأمر كما زعمتم بأنه لا عواقب وخيمة لأعمالكم هذه ، فإن من يظن تكريم الله له يسهل عليه العمل بالوظائف في أموره وشؤونه ف ( إِذا دُكَّتِ الْأَرْضُ ) أي كسر كل شيء على ظهرها ( دَكًّا دَكًّا ) كسرا كسرا ، من جبال ومرتفعات وأنصبة وأشباهها ، وذلك لأن الأرض تسوى حتى لا يبقى على ظهرها عوج ولا أمت. وَجاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا (22) وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنْسانُ وَأَنَّى لَهُ الذِّكْرى (23) يَقُولُ يا لَيْتَنِي قَدَّمْتُ لِحَياتِي (24) فَيَوْمَئِذٍ لا يُعَذِّبُ عَذابَهُ أَحَدٌ (25)` },
            { text: "وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا", tafsir: `أي أمر ربك ، كما يظهر ملوك الدنيا في هيبة وجلال ، فإن الهيبة والجلال التي تظهر يوم القيامة لله سبحانه تكون بمثابة مجيء الله سبحانه ، لكنه حيث كان منزها عن الجسم ولوازمه ، يجيء آثار جلاله ( وَ ) جاء ( الْمَلَكُ ) المربطون بذلك اليوم في حال كونهم ( صَفًّا صَفًّا ) أي مصطفين صفوفا متعددة.` },
            { text: "وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ", tafsir: `أي يوم القيامة ( بِجَهَنَّمَ ) بأن تمتد نيرانها إلى المحشر بعد ما كانت مبتعدة مستعدة لالتهام الكفار والعاصين ( يَوْمَئِذٍ ) أي في هذا اليوم ـ وأصله يوم إذ كان كذا ـ ( يَتَذَكَّرُ الْإِنْسانُ ) أي يتعظ ويخاف ويهتدي ( وَ ) لكن ( أَنَّى لَهُ الذِّكْرى ) ؟ أي من أين ينفعه التذكر في ذلك اليوم ، فقد مضى وقت نفع التذكر ، وإنما هناك جزاء فقط لا عمل.` },
            { text: "يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى", tafsir: `الإنسان العاصي ، ( يا لَيْتَنِي قَدَّمْتُ ) عملا صالحا ( لِحَياتِي ) هذه التي تبقى إلى الأبد ، ولكن لا ينفعه التمني ، كما يقول المثل « ندم زيد ولما ينفعه الندم » .` },
            { text: "فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ", tafsir: `أي في ذلك اليوم ( لا يُعَذِّبُ عَذابَهُ أَحَدٌ ) أي لا يعذب مثل عذاب الله أحد ، فإن عذابه ليس كسائر أنواع عذاب الناس بعضهم لبعض ، وإنما هو عذاب غريب عجيب. وَلا يُوثِقُ وَثاقَهُ أَحَدٌ (26) يا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ (27) ارْجِعِي إِلى رَبِّكِ راضِيَةً مَرْضِيَّةً (28) فَادْخُلِي فِي عِبادِ ي (29) وَادْخُلِي جَنَّتِي (30)` },
            { text: "وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ", tafsir: `يومئذ ( لا يُوثِقُ وَثاقَهُ ) أي مثل وثاقه سبحانه وتعالى ( أَحَدٌ ) والوثاق هو الشد ، يقال أوثقته أي شددته. [28] ثم يخاطب المؤمنون بقوله سبحانه ( يا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ) من أهوال ذلك اليوم ، لما عملت في الدنيا من الإيمان والإطاعة.` },
            { text: "يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ", tafsir: `` },
            { text: "ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً", tafsir: `أي إلى ثوابه وجزائه في حال كونك ( راضِيَةً ) عن الله سبحانه ( مَرْضِيَّةً ) له تعالى ، فإنه سبحانه راض عنك بسبب إيمانك وأعمالك.` },
            { text: "فَٱدْخُلِى فِى عِبَٰدِى", tafsir: `زمرة ( عِبادِي ) الصالحين.` },
            { text: "وَٱدْخُلِى جَنَّتِى", tafsir: `` }
        ]
    },
    90: { // سورة البلد
        name: "البلد",
        basmalaTafsir: ``,
        verses: [
            { text: "لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ", tafsir: `والمراد به مكة ، و « لا » إما للنفي جيء بها للتلويح إلى القسم مع تعظيم المقسم به ، وإما زائدة ، فالمعنى أقسم بهذا البلد ، والآية الثانية تناسب الأمرين باعتبارين.` },
            { text: "وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ", tafsir: `يا رسول الله ( حِلٌ ) أي مقيم قد حللت ( بِهذَا الْبَلَدِ ) فإنه قد تشرف بك ، فإن شرف المنزل بشرف النازل ، و « الحل » بمعنى الحال ، وكلاهما بمعنى الساكن ، فهذا البلد إنما يقسم به لشرفه بك أو يعظم فلا يقسم به لشرفه بك.` },
            { text: "وَوَالِدٍ وَمَا وَلَدَ", tafsir: `قسما ب ( والِدٍ وَما وَلَدَ ) أي كل والد وكل ولد ، أو المراد آدم عليه‌السلام وأولاده ، فإن كل خلق الله عظيم يصح أن يجعل في معرض القسم. نعم ليس لنا أن نحلف بكل شيء ، لما ورد من قوله صلى‌الله‌عليه‌وآله‌وسلم : « من كان حالفا فليحلف بالله أو ليسكت » (1) . [5] وجواب القسم قوله : ( لَقَدْ خَلَقْنَا الْإِنْسانَ فِي كَبَدٍ ) أي في تعب ومشقة ، فإنه يكابد الشدائد والمصائب والمتاعب ، فإن « الكبد » لغة بمعنى شدة الأمر ، والمعنى أنه لا يزال يكابد الأتعاب ـ بما قدر الله له وللكون من الأنظمة ـ ولذا قال تعالى في حديث قدسي « إني ما جعلت الراحة في الدنيا والناس يطلبونها فيها فلا يجدوها » . [6] إن الإنسان الذي خلق في عناء ومشقة ، ليدل ذلك على ضعفه وعجزه إذا رأى بعض القوة في ذاته عتا وتكبر وزعم أنه لا قادر عليه ( 1) متشابه القرآن ومختلفه : ج 2 ص 198. أَ يَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ (5) يَقُولُ أَهْلَكْتُ مالاً لُبَداً (6) أَ يَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ (7) أَ لَمْ نَجْعَلْ لَهُ عَيْنَيْنِ (8) وَلِساناً وَشَفَتَيْنِ (9) ( أَ يَحْسَبُ ) أي هل يظن ويزعم الإنسان ( أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ ) بسلبه القوة والثروة والحياة وما أشبه ؟ [7] وإذا قيل له : ابتغ مرضاة الله ببذل الأموال في سبيله لأنك عبد عاجز ضعيف له سبحانه ، وهو قادر على تقليبك كيف يشاء ( يَقُولُ ) في الجواب : ( أَهْلَكْتُ ) في الإنفاق ( مالاً لُبَداً ) أي كثيرا ، مأخوذ من تلبد الشيء إذا تراكم بعضه على بعضه ، وحسبي ما أنفقت ـ كما أن هذا هو منطق الأثرياء غالبا ـ .` },
            { text: "لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ", tafsir: `` },
            { text: "أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ", tafsir: `` },
            { text: "يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا", tafsir: `` },
            { text: "أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ", tafsir: `أي يزعم ( أَنْ لَمْ يَرَهُ أَحَدٌ ) حيث أنفق ؟ بل إنّ الله رآه وعرف قدر إنفاقه ولم يكن ما أنفق كثيرا بالنسبة إلى أمواله وبالنسبة إلى مقابلته بالثواب المرجو في الآخرة للمنفقين. قيل : إنها نزلت في الحرث ، وذلك أنه أذنب ذنبا فاستفتى رسول الله ؟ فأمره أن يكفر ، فقال : لقد ذهب مالي في الكفارات والنفقات منذ دخلت في دين محمد صلى‌الله‌عليه‌وآله‌وسلم . [9] إنه يبخل عن بذل بعض ماله في سبيل الله الذي أودع فيه القوى التي لا تثمن بثمن فلم يؤدّ شكرها ، ولم يبصر بسببها طريق الرشاد ( أَ لَمْ نَجْعَلْ لَهُ عَيْنَيْنِ ) ليبصر بهما ويرى طريقه ؟` },
            { text: "أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ", tafsir: `` },
            { text: "وَلِسَانًا وَشَفَتَيْنِ", tafsir: `؟ لينطق به ويتجمل بالشفة لعدم قبح منظره بفغر الفم. وَهَدَيْناهُ النَّجْدَيْنِ (10) فَلا اقْتَحَمَ الْعَقَبَةَ (11) وَما أَدْراكَ مَا الْعَقَبَةُ (12) فَكُّ رَقَبَةٍ (13) أَوْ إِطْعامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ (14) يَتِيماً ذا مَقْرَبَةٍ (15)` },
            { text: "وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ", tafsir: `أي أرشدناه ( النَّجْدَيْنِ ) ؟ أي سبيل الخير وسبيل الشر ، وأصل « النجد » هو العلو ، وكأن الطريق موجب لارتفاع الإنسان ارتفاعا معنويا بوصوله إلى حاجته ، أو لظهور الطريق سمي نجدا تشبيها بالمرتفع من الأرض.` },
            { text: "فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ", tafsir: `« الاقتحام » هو الدخول في الشيء بشدة ، و « عقبة » هي الطريق الصعب في الجبل ، أي أن الإنسان لم يشكر تلك النعم التي أعطيناها إياه باقتحام الأمور الحسنة والعمل بها ، وسميت عقبة لشدة أمرها على الإنسان.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ", tafsir: `أيها السامع ( مَا الْعَقَبَةُ ) أي ما هي العقبة ؟ وهذا التعبير لتعظيم أمرها والإجلال لها ، ثم فسرت العقبة بأنه عتق العبد والإطعام. [14] العقبة هي ( فَكُّ رَقَبَةٍ ) أي تحرير العبد من إسار الرق ، وإنما أطلق على الإنسان « الرقبة » بعلاقة الجزء والكل ـ كما قرر في البلاغة.` },
            { text: "فَكُّ رَقَبَةٍ", tafsir: `` },
            { text: "أَوْ إِطْعَٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ", tafsir: `« أو » بمعنى الواو ، يعني أن من أفراد « العقبة » إطعام الناس ( فِي يَوْمٍ ذِي مَسْغَبَةٍ ) « السغب » هو الجوع ، والمسغبة المجاعة.` },
            { text: "يَتِيمًا ذَا مَقْرَبَةٍ", tafsir: `مفعول « إطعام » أي ليطعم الطفل الذي مات أبوه ( ذا مَقْرَبَةٍ ) أي ذا قرابة من المطعم ، فإن الإحسان إلى الأقرباء أفضل من الإحسان أَوْ مِسْكِيناً ذا مَتْرَبَةٍ (16) ثُمَّ كانَ مِنَ الَّذِينَ آمَنُوا وَتَواصَوْا بِالصَّبْرِ وَتَواصَوْا بِالْمَرْحَمَةِ (17) أُولئِ كَ أَصْحابُ الْمَيْمَنَةِ (18) إلى غيرهم ، كما قال عليه‌السلام : « لا صدقة وذو رحم كاشح » ـ (1) .` },
            { text: "أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ", tafsir: `وهو الفقير الذي أسكنه الفقر ، فإن الأغنياء يتحركون في مختلف حوائجهم ، أما الفقراء فإنهم حيث لا مال لهم لا يتمكنون من التصرف في الشؤون ( ذا مَتْرَبَةٍ ) بمعنى الحاجة الشديدة من قولهم « ترب الرجل » إذا افتقر ، وأصله من التراب ، لأن الفقر يلازم التراب ، لعدم فراش له ليقيه منه ، فالمعنى قد لصق بالتراب من شدة فقره.` },
            { text: "ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ", tafsir: `لترتيب الكلمة لا ترتيب المطلب ( كانَ ) ذلك الإنسان الذي لم يقتحم العقبة ( مِنَ الَّذِينَ آمَنُوا ) بالله ورسوله وما جاء به ، وهذا عطف على النفي ، أي لم يقتحم العقبة مع كونه مؤمنا ( وَتَواصَوْا بِالصَّبْرِ ) أي أوصى بعضهم بعضا بأن يصبر على الشدائد ، طاعة كانت أو معصية أو مصيبة ، بأن يعمل الأول ، ويترك الثاني ، ولا يجزع في الثالث ( وَتَواصَوْا بِالْمَرْحَمَةِ ) أي برحم الناس والعطف عليهم ، فإن « مرحمة » مصدر ميمي بمعنى الرحم.` },
            { text: "أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ", tafsir: `المتصفون بفك الرقاب وإطعام الطعام والتواصي بالصبر والمرحمة ( أَصْحابُ الْمَيْمَنَةِ ) يؤخذ بهم ـ في القيامة ـ ناحية اليمين نحو الجنان ، ويعطون كتابهم بأيمانهم ، أو أنهم أصحاب يمن وبركة. ( 1) راجع من لا يحضره الفقيه : ج 2 ص 68 ، وردت كلمة محتاج بدل كاشح في الحديث. وَالَّذِينَ كَفَرُوا بِآياتِنا هُمْ أَصْحابُ الْمَشْأَمَةِ (19) عَلَيْهِمْ نارٌ مُؤْصَدَةٌ (20)` },
            { text: "وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ", tafsir: `حججنا الدالة على التوحيد وسائر الأصول ( هُمْ أَصْحابُ الْمَشْأَمَةِ ) فإنهم كانوا أصحاب شؤم على أنفسهم.` },
            { text: "عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ", tafsir: `` }
        ]
    },
    91: { // سورة الشمس
        name: "الشمس",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلشَّمْسِ وَضُحَىٰهَا", tafsir: `أي قسما بالشمس ( وَ ) قسما ب ( ضُحاها ) أي انبساط ضوءها في الآفاق.` },
            { text: "وَٱلْقَمَرِ إِذَا تَلَىٰهَا", tafsir: `قسما ب ( الْقَمَرِ إِذا تَلاها ) أي تبع الشمس ، فأخذ من ضوئها وسار في عقبها.` },
            { text: "وَٱلنَّهَارِ إِذَا جَلَّىٰهَا", tafsir: `قسما ب ( النَّهارِ إِذا جَلَّاها ) أي جلى الشمس وأظهرها وفيه لطف حيث أسند تجلية الشمس إلى النهار من باب « القلب » ، فكأن النهار لشدة ضوئه يوضح الشمس ويظهرها ، كما قال أهل البلاغة في قوله « كما طينت بالفدن السياعا » .` },
            { text: "وَٱلَّيْلِ إِذَا يَغْشَىٰهَا", tafsir: `قسما ب ( اللَّيْلِ إِذا يَغْشاها ) أي يغشي الشمس فيغطيها عن الأبصار ويخفيها.` },
            { text: "وَٱلسَّمَآءِ وَمَا بَنَىٰهَا", tafsir: `قسما ب ( السَّماءِ وَما بَناها ) أي « وقسما بمن بنى السماء » والمراد به الله تعالى ، أو « ما » مصدرية ، أي وبنائها المحكم المتقن.` },
            { text: "وَٱلْأَرْضِ وَمَا طَحَىٰهَا", tafsir: `قسما ب ( الْأَرْضِ وَما طَحاها ) « الطحو » بمعنى البسط ، أي ومن بسطها وهو الله ، أو طحوها ، على أن تكون « ما » مصدرية ـ كما سبق ـ .` },
            { text: "وَنَفْسٍ وَمَا سَوَّىٰهَا", tafsir: `أي قسما بكل نفس ، والإتيان بها نكرة للتفنن والبلاغة ( وَما سَوَّاها ) أي الذي صنعها ، وكون « ما » موصولة ـ هنا ـ أقرب ، بقرينة الآية التالية. فَأَلْهَمَها فُجُورَها وَتَقْواها (8) قَدْ أَفْلَحَ مَنْ زَكَّاها (9) وَقَدْ خابَ مَنْ دَسَّاها (10) كَذَّبَتْ ثَمُودُ بِطَغْواها (1 1) إِذِ انْبَعَثَ أَشْقاها (12)` },
            { text: "فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا", tafsir: `أي عرّفها بطريق الإلقاء في القلب ( فُجُورَها ) أي عصيانها ( وَتَقْواها ) أي إطاعتها ، فإن كل إنسان يميز بين الخير والشر والطاعة والعصيان ، وهذه الأقسام في هذه السورة وغيرها إنما تلفت الأنظار إلى هذه الآيات والمعارف ، بالإضافة إلى كونها حلفا ، فلا يقال : أية حاجة لهذه الأيمان ؟` },
            { text: "قَدْ أَفْلَحَ مَن زَكَّىٰهَا", tafsir: `هذا هو المقسم له ، أي فاز من زكى نفسه وطهرها من الآثام والكفر.` },
            { text: "وَقَدْ خَابَ مَن دَسَّىٰهَا", tafsir: `أي خسر ( مَنْ دَسَّاها ) أي أخملها وأخفى محلها بالكفر والعصيان ، فإن « دس » نقيض « زكى » . [12] ثم جاء السياق ليهدد الذين يدسون أنفسهم بأن مصيرهم مصير أولئك الأقوام المكذبين من قبلهم ( كَذَّبَتْ ثَمُودُ ) أي قبيلة ثمود وهم قوم صالح عليه‌السلام ( بِطَغْواها ) أي بسبب طغيانها ، فإن الطغيان يوجب التكذيب والكفر كما قال سبحانه ( ثُمَّ كانَ عاقِبَةَ الَّذِينَ أَساؤُا السُّواى أَنْ كَذَّبُوا بِآياتِ اللهِ ) (1) . و « طغوى » و « طغيان » بمعنى واحد ، وهو مجاوزة الحد في العصيان.` },
            { text: "كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ", tafsir: `` },
            { text: "إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا", tafsir: `فقد بعثه الأشقياء لارتكاب هذه الجناية ، فانبعث ( أَشْقاها ) أي أشقى ثمود ، بمعنى الفرد الذي هو أكثر شقوة من غيره ( 1) الروم : 11. فَقالَ لَهُمْ رَسُولُ اللهِ ناقَةَ اللهِ وَسُقْياها (13) فَكَذَّبُوهُ فَعَقَرُوها فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاها (14) وَلا يَخافُ عُقْباها (15) من أفراد القبيلة ، وهو « قدار » ، وهو الذي عقر الناقة.` },
            { text: "فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا", tafsir: `تفريع على « كذبت » لا على « انبعث » ، والضمير عائد إلى قبيلة ثمود ( رَسُولُ اللهِ ) والمراد به صالح عليه‌السلام : احذروا ( ناقَةَ اللهِ ) بأن تمسوها بسوء ( وَ ) احذروا ( سُقْياها ) أي شربها من الماء فلا تزجروها في شربها ، فقد كان هناك نهر ، وقرر صالح أن يكون ماء النهر يوما للناقة وتعطي بعوضه اللبن بقدر احتياج القبيلة ، ويوما للناس ، وقال لهم : إن مسستم الناقة بسوء أخذكم العذاب ـ كما تقدم تفصيل القصة ـ .` },
            { text: "فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا", tafsir: `أي كذب أهل قبيلة ثمود صالحا عليه‌السلام ـ المتقدم باسم « رسول الله » ـ ( فَعَقَرُوها ) أي نحروا الناقة وضربوا يديها ورجليها بالسيف ، والعاقر كان واحدا لكن تآمرهم على ذلك ورضاهم به أوجب إسناد الفعل إلى جميعهم ( فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ ) أي دمر عليهم الله تعالى ، فإن الدمدمة ترديد الحال المستكره بمضاعفة ما فيه المشقة ( بِذَنْبِهِمْ ) أي بسبب ذنبهم بعقر الناقة ( فَسَوَّاها ) أي سوى الله الدمدمة عليهم أجمعين بحيث لم يفلت منها أحد ، أو سوّى الله أرضهم بحيث استوت فلا شيء فيها.` },
            { text: "وَلَا يَخَافُ عُقْبَٰهَا", tafsir: `` }
        ]
    },
    92: { // سورة الليل
        name: "الليل",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلَّيْلِ إِذَا يَغْشَىٰ", tafsir: `أي قسما بالليل ( إِذا يَغْشى ) أي يحيط بظلمته على الأشياء ، وتخصيص بعض الأقسام بأمور خاصة ، من باب التفنن في البلاغة.` },
            { text: "وَٱلنَّهَارِ إِذَا تَجَلَّىٰ", tafsir: `قسما ب ( النَّهارِ إِذا تَجَلَّى ) أي ظهر وبان وأضاء.` },
            { text: "وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ", tafsir: `قسما ب ( ما خَلَقَ الذَّكَرَ وَالْأُنْثى ) « ما » إما موصولة ، أي الذي خلق ، والمراد به الله سبحانه ، وإنما جيء ب « ما » دون « من » لأن « من » في الغالب يستعمل للبشر ونحوهم ، وإما مصدرية أي قسما يخلق الصنفين.` },
            { text: "إِنَّ سَعْيَكُمْ لَشَتَّىٰ", tafsir: `أيها الناس ، في الأمور ، وتطلبكم للأشياء ( لَشَتَّى ) جمع شتيت كمرضى جمع مريض ، أي أنه مختلف ، فمن طالب دنيا ومن طالب آخرة ، والحلف على ذلك باعتبار ما يعقبه من النتائج ، أو لتبديد أوهام الزاعمين بأن السعي ليس إلا للدنيا فحسب ، إذ ليس هناك آخرة.` },
            { text: "فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ", tafsir: `المال في سبيل الله ( وَاتَّقى ) الكفر والمعاصي.` },
            { text: "وَصَدَّقَ بِٱلْحُسْنَىٰ", tafsir: `أي بالكلمة الحسنى ، وهي الشهادتان ، وحيث إن المقام كان في الإعطاء تقدم ، ثم ذكر التقوى لأنه من أقسام الإعطاء ، ثم جاء دور العقيدة بعد ذين الأمرين.` },
            { text: "فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ", tafsir: `أي سنهوّن عليه الطريقة اليسرى ، وهي طريقة الطاعة ، أو نيسره للحياة اليسرى ، أي الأسهل ، فإن من تبع نهج وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنى (8) وَكَذَّبَ بِالْحُسْنى (9) فَسَنُيَسِّرُهُ لِلْعُسْرى (10) وَما يُغْنِي ع َنْهُ مالُهُ إِذا تَرَدَّى (11) الإسلام سهلت عليه الأمور لما في الإسلام من المناهج السهلة الموجبة للسعادة والرفاه يقال « يسره » إذا سهل عليه ، و « يسرى » مؤنث « أيسر » بمعنى الأسهل.` },
            { text: "وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ", tafsir: `بماله فلم ينفقه في سبيل الله ( وَاسْتَغْنى ) أي طلب الغنى بجمع المال والبخل من إنفاقه.` },
            { text: "وَكَذَّبَ بِٱلْحُسْنَىٰ", tafsir: `أي بالكلمة الحسنة ، وهي كلمة الشهادتين أو المراد في الموضعين « العدة الحسنى » وهي الثواب والجنة.` },
            { text: "فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ", tafsir: `أي سنهون عليه الطريقة الأعسر وهي طريقة الكفر ، وهذا على سبيل المزاوجة في الكلام ـ من قبيل ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ ) (1) ، إذ الله سبحانه لا يسهل على أحد سبيل العسر ، وإنما المراد أنه سبحانه يخلي بينه وبين ما يعمل ـ .` },
            { text: "وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ", tafsir: `أي لا يفيده ماله الذي بخل به ( إِذا تَرَدَّى ) أي هلك وسقط في الهاوية. روي أن رجلا كانت له نخلة فرعها في دار رجل فقير ذي عيال وكان الرجل إذا جاء فدخل الدار وصعد النخلة ليأخذ منها التمر فربما سقطت التمرة فيأخذها صبيان الفقير ، فينزل الرجل من النخلة حتى يأخذ التمر من أيديهم ، فإن وجدها في فم أحدهم أدخل إصبعه حتى يأخذ التمرة من فيه ، فشكا ذلك الرجل إلى النبي صلى‌الله‌عليه‌وآله‌وسلم وأخبره بما يلقى من صاحب النخلة ، فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : اذهب ، ولقي رسول الله ( 1) البقرة : 195. إِنَّ عَلَيْنا لَلْهُدى (12) وَإِنَّ ل َنا لَلْآخِرَةَ وَالْأُولى (13) صاحب النخلة فقال : تعطيني نخلتك المائلة التي فرعها في دار فلان ولك بها نخلة في الجنة ؟ فقال له الرجل : إن لي نخلا كثيرا وما فيه نخلة أعجب إليّ تمرة منها. قال : ثم ذهب الرجل ، فقال رجل كان يسمع الكلام من رسول الله ـ وقيل اسمه أبو دحداح ـ : يا رسول الله أ تعطيني ما أعطيت الرجل نخلة في الجنة إن أنا أخذتها ؟ قال : نعم. فذهب الرجل ولقي صاحب النخلة فساومها منه ، فقال له : أشعرت أن محمدا صلى‌الله‌عليه‌وآله‌وسلم أعطاني بها نخلة في الجنة فقلت له يعجبني تمرها وإن لي نخلا كثيرا فما فيه نخلة أعجب إلى تمرة منها. فقال له الآخر أ تريد بيعها ؟ فقال : لا إلا أن أعطى ما لا أظنه أعطى ؟ قال : فما هناك ؟ قال : أربعون نخلة ، فقال الرجل : جئت بعظيم تطلب بنخلتك المائلة أربعين نخلة ، ثم سكت عنه ، فقال له : أنا أعطيك أربعين نخلة ، فقال له : اشهد إن كنت صادقا ، فمر إلى أناس ، فدعاهم فأشهد له بأربعين نخلة ، ثم ذهب إلى النبي صلى‌الله‌عليه‌وآله‌وسلم فقال : يا رسول الله إن النخلة قد صارت في ملكي ، فهي لك. فذهب رسول الله إلى صاحب الدار ، فقال له : النخلة لك ولعيالك ، فأنزل الله تعالى « والليل » فمن أعطى « أبو دحداح » ومن بخل « صاحب النخلة » (1) .` },
            { text: "إِنَّ عَلَيْنَا لَلْهُدَىٰ", tafsir: `أي أن اللازم على الله سبحانه ـ بقاعدة اللطف ـ أن ينصب الأدلة ويرسل الرسل ، أما الاتباع والاهتداء فعلى الناس من شاء اهتدى ومن شاء بقي على ضلاله.` },
            { text: "وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ", tafsir: `أي الدنيا ، فمن اهتدى منحناه السعادة في ( 1) بحار الأنوار : ج 22 ص 60. فَأَنْذَرْتُكُمْ ناراً تَلَظَّى (14) لا يَصْلاها إِلاَّ الْأَشْقَى (15) الَّذِي كَذَّبَ وَتَوَلَّى (16) وَسَيُجَنَّبُهَا الْأَتْقَى (17) الَّذِي يُؤْتِي مالَهُ يَتَزَكَّى (18) وَما لِأَحَدٍ عِن ْدَهُ مِنْ نِعْمَةٍ تُجْزى (19) الدارين ، ومن بقي على كفره حرم من خير الدنيا وسعادة الآخرة.` },
            { text: "فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ", tafsir: `أيها الناس ( ناراً تَلَظَّى ) أي تتلظى ـ حذفت إحدى تائيه لقاعدة اجتماع التائين على رأس المضارع ـ ومعنى التلظي المتلهب والمتوقد وهذه النار عذابها أشد.` },
            { text: "لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى", tafsir: `أي لا يدخلها ملازما لها ( إِلَّا الْأَشْقَى ) أي الأكثر شقوة ، وهو الكافر ، مقابل العاصي الذي هو أقل شقوة فإنه وإن دخل النار لكنه لا يلازمها.` },
            { text: "ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ", tafsir: `بآيات الله تعالى ، وكفر به ( وَتَوَلَّى ) أي أعرض عن الحق.` },
            { text: "وَسَيُجَنَّبُهَا ٱلْأَتْقَى", tafsir: `أي سيجنب النار ، ويجعل منها على جانب ، ودخول « السين » لكون القيامة في المستقبل ( الْأَتْقَى ) أي الأكثر تقوى وهو المؤمن المطيع ، وأما المؤمن غير المطيع فإنه يدخل فيها وإن خرج بعد مدة.` },
            { text: "ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ", tafsir: `أي ينفق ماله في سبيل الله تعالى ( يَتَزَكَّى ) أي يطلب الزكاة والطهارة بإعطاء ماله ، فإن الإنفاق يطهر القلب من الرذائل.` },
            { text: "وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ", tafsir: `أي لا يعطي الأتقى ماله لأن لأحد عليه إحسانا ، يريد بهذا الإنفاق جزاء ذلك المحسن ، و « من » لنفي إِلاَّ ابْتِغاءَ وَجْهِ رَبِّهِ الْأَع ْلى (20) وَلَسَوْفَ يَرْضى (21) الجنس .. . والمراد أنه لا يعطي جزاء لإحسان ، وإنما عطاؤه لوجه الله سبحانه.` },
            { text: "إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ", tafsir: `أي طلب رضى ( وَجْهِ رَبِّهِ الْأَعْلى ) أي رضاه سبحانه ، وإنما أضيف إلى « وجه » لأنه الذي يظهر عليه أثر الرضا في الإنسان ، فهو من باب تشبيه المعقول بالمحسوس ، والاستثناء منقطع ، والتقدير لا يعطي ماله جزاء ، بل إنما يعطي قربة إلى الله سبحانه.` },
            { text: "وَلَسَوْفَ يَرْضَىٰ", tafsir: `` }
        ]
    },
    93: { // سورة الضحى
        name: "الضحى",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلضُّحَىٰ", tafsir: `أي قسما بالضحى ، وهو وقت ارتفاع الشمس في كبد السماء بحيث يعم نورها ، والواو في مثل هذه المواضع استئنافية لتمليح الكلام وتوحيد السياق.` },
            { text: "وَٱلَّيْلِ إِذَا سَجَىٰ", tafsir: `أي قسما بالليل ( إِذا سَجى ) أي سكن واستقر ظلامه ، فإن « السجو » بمعنى السكون.` },
            { text: "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", tafsir: `يا رسول الله ( رَبُّكَ ) أي ما ترك عنك الوحي توديعا لك ، بأن يكون كالمفارق الذي يودع صديقه ( وَما قَلى ) أي ما قلاك ، بمعنى ما أبغضك ، فإن القلى بمعنى المبغض. روى عن الإمام الباقر عليه‌السلام إن جبرئيل أبطأ على رسول الله صلى‌الله‌عليه‌وآله‌وسلم وأنه كانت أول سورة نزلت ( اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ) ثم أبطأ عليه ، فقالت خديجة : لعل ربك قد تركك فلا يرسل إليك ؟ فأنزل الله تبارك وتعالى ( ما وَدَّعَكَ رَبُّكَ وَما قَلى ) (1) .` },
            { text: "وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ", tafsir: `« اللام » للتأكيد ( خَيْرٌ لَكَ ) يا رسول الله ( مِنَ الْأُولى ) أي الدنيا ، فقد أعد لك الخير هناك ، فكيف يتركك ويقلاك في منتصف الطريق ؟` },
            { text: "وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ", tafsir: `يا رسول الله ، في الآخرة ( رَبُّكَ ) بما تشاء ( فَتَرْضى ) من كثرة فضله وإحسانه ، ومن جملة ما يعطى صلى‌الله‌عليه‌وآله‌وسلم الشفاعة ـ كما لا يخفى. [7] ثم أخذ السياق يعدد بعض نعم الله سبحانه عليه سابقا ليؤكد أنه صلى‌الله‌عليه‌وآله‌وسلم ( 1) تفسير القمي : ج 2 ص 428. أَ ل َمْ يَجِدْكَ يَتِيماً فَآوى (6) وَوَجَدَكَ ضَالاًّ فَهَدى (7) وَوَجَدَكَ عائِلاً فَأَغْنى (8) فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ (9) وَأَمَّا السَّائِلَ فَلا تَنْهَرْ (10) وَأَمَّا بِ نِعْمَةِ رَبِّكَ فَحَدِّثْ (11) الآن في وسط الطريق بين نعمة سبقت ونعمة تأتي فكيف يقلاه بعد ذلك ؟ ( أَ لَمْ يَجِدْكَ ) الله ( يَتِيماً ) قد مات أبوك ( فَآوى ) أي آواك ، وأعطاك مأوى ومنزلا وعشيرة تأوي إليهم ، في حين أن اليتيم كان ذليلا مهانا لدى أهل الجاهلية ؟` },
            { text: "أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ", tafsir: `` },
            { text: "وَوَجَدَكَ ضَآلًّا فَهَدَىٰ", tafsir: `يا رسول الله ( ضَالًّا ) قد تفردت في أناس جاهليين كالشيء الثمين الذي يضل في صحراء مقفرة ( فَهَدى ) الناس إليك فأخرجك عن الوحشة والتفرد حيث لا يهتدي الناس ؟` },
            { text: "وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ", tafsir: `الله ( عائِلاً ) أي فقيرا لا مال لك ( فَأَغْنى ) أغناك بالمال ، كمال خديجة عليها‌السلام وغيره. [10] وإذ قد ذاق الرسول مرارة اليتم والضلال والفقر ، فليحن على البائسين ويعطف على المنكوبين ( فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ ) أي لا تقهره يا رسول الله ، بأن تزعجه وتظلمه. والرسول وإن كان منزها عن ذلك لكن الأوامر والنواهي شاملة له كشمولها لغيره من سائر المكلفين.` },
            { text: "فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ", tafsir: `` },
            { text: "وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ", tafsir: `الذي يسأل المال ، وهو الفقير ومن أشبهه ( فَلا تَنْهَرْ ) أي لا تطرده خائبا ، بل أعطه شيئا ، أورده ردا جميلا.` },
            { text: "وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ", tafsir: `` }
        ]
    },
    94: { // سورة الشرح
        name: "الشرح",
        basmalaTafsir: ``,
        verses: [
            { text: "أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ", tafsir: `يا رسول الله ( صَدْرَكَ ) ؟ وشرح الصدر توسعته بالأخلاق الفاضلة ، فكأن صدر من لم يكن حليما أو سخيا أو عالما ـ أو ما أشبه ـ ضيق كالإناء الضيق الذي لا يحتوي إلا على شيء قليل ، والنسبة إلى الصدر لأن القلب الذي هو محل الفضائل في الصدر ، ولعل وجه ذلك أن الإنسان إذا ضاق بأمر حمى قلبه ، فيحتاج إلى هواء أكثر لتبريد القلب ، فتنتفخ الرئة انتفاخا كثيرا مما يضيق الصدر حسا ، ثم أن في الاستفهام حلاوة ليس في الإخبار.` },
            { text: "وَوَضَعْنَا عَنكَ وِزْرَكَ", tafsir: `أي حططنا ( عَنْكَ ) يا رسول الله ( وِزْرَكَ ) أي حملك الثقيل ، فإن « الوزر » هو الحمل ، وذلك بشرح صدرك حتى لا يثقل عليك حمل التبليغ ، وهذا ما يحسه كل إنسان مرشد ، فإنه في أول أمره يرى حملا ثقيلا عليه من جراء الإرشاد ، ثم يتسع صدره ـ بفضله سبحانه ـ ويحس كأنه وضع عنه الثقل ، حتى يشعر أحيانا بأنه لا حمل إطلاقا.` },
            { text: "ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ", tafsir: `من ثقله ، و « أنقض » بمعنى أسمع الصوت فإن الإنسان إذا حمل حملا ثقيلا سمع لظهره فرقعة ، وهذا هو الإنقاض ـ وذلك من باب التشبيه للمعقول بالمحسوس ـ .` },
            { text: "وَرَفَعْنَا لَكَ ذِكْرَكَ", tafsir: `يا رسول الله ( ذِكْرَكَ ) حتى يعرفك كل أحد بالصدق والأمانة وما أشبه ذلك ، هذا بالإضافة إلى ما رفعه سبحانه ـ بعد ذلك ـ من ذكره في المآذن وغيرها. فَإِنَّ مَعَ الْعُسْرِ يُسْراً (5) إ ِنَّ مَعَ الْعُسْرِ يُسْراً (6) [6] وإذ تقدم بيان أن النبي صلى‌الله‌عليه‌وآله‌وسلم صار في اليسر بعد ما كان في العسر ، جاء السياق يؤكد هذه الحقيقة في مختلف أدوار الحياة لكل إنسان ( فَإِنَّ مَعَ الْعُسْرِ يُسْراً ) فإذا عسر الأمر على الإنسان واشتد كان لا بد وأن يأتي بعده يسر وسهولة.` },
            { text: "فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا", tafsir: `` },
            { text: "إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا", tafsir: `هذا للتأكيد ، مع أن فيه تأسيسا ، وهو كون « يسر » الثاني غير « يسر » الأول لأنه منكر ، بخلاف « العسر » في الموضعين فإنه واحد ، لكون اللام ـ سواء كان للعهد أو الجنس ـ توجب الإشارة إلى الحصة المعهودة ، ولذا لو قلت « اشتريت فرسا ثم بعت الفرس » فهم ان المبيع هو المشترى ولو قلت « اشتريت فرسا ثم بعت فرسا » فهم أن المبيع غير المشترى. و قد روي أن النبي صلى‌الله‌عليه‌وآله‌وسلم خرج مسرورا فرحا وهو يضحك ويقول : لن يغلب عسر يسرين فان مع العسر يسرا ، إن مع العسر يسرا (1) . أقول : وقد نظم الشاعر ذلك بقوله : إذا ضاقت بك الدنيا تفكر في ألم نشرح تجد يسرين مع عسر إذا ذكرتها تفرح ( 1) مجمع البيان : ج 1 ص 390. فَإِذا فَرَغْتَ فَانْصَبْ ( 7) وَإِلى رَبِّكَ فَارْغَبْ (8)` },
            { text: "فَإِذَا فَرَغْتَ فَٱنصَبْ", tafsir: `يا رسول الله من أمورك الخاصة ( فَانْصَبْ ) في الدعاء والعبادة ، من « النصب » بمعنى التعب ، أي أتعب نفسك في الاشتغال بالله سبحانه.` },
            { text: "وَإِلَىٰ رَبِّكَ فَٱرْغَب", tafsir: `` }
        ]
    },
    95: { // سورة التين
        name: "التين",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلتِّينِ وَٱلزَّيْتُونِ", tafsir: `أي قسما بهاتين الفاكهتين ، وإنما جاء الحلف بهما لكثرتهما في الشام وحواليها المباركة ـ التي يراد التلميح إليها لكونها مبعث الأنبياء ومهبط ملائكة السماء ـ .` },
            { text: "وَطُورِ سِينِينَ", tafsir: `قسما ب ( طُورِ سِينِينَ ) يعني الجبل الذي كلم الله عليه موسى و « سينين » و « سيناء » لغتان فيه فالقسم برزق الله المادي الفواكه ، وفضله المعنوي الرسالات.` },
            { text: "وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ", tafsir: `قسما ب ( هذَا الْبَلَدِ ) وهو مكة ( الْأَمِينِ ) الذي يأمن فيه الخائف ، فكأنه لا يخون وارده بإهلاك وإيذاء.` },
            { text: "لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ", tafsir: `هذا جواب القسم ، والتقويم بمعنى تصيير الشيء على ما ينبغي أن يكون عليه من التأليف والتعديل يعني الإنسان مخلوق في أحسن طراز من جهة حواسه وظواهره ، ومن جهة مشاعره وأجهزته ، وهذا يناسب القسم ، لأن الكل إحسان وإفضال ففاكهة ، ووحي ، وإنسان ينتفع بهما في مادياته ومعنوياته.` },
            { text: "ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ", tafsir: `أي أرجعنا الإنسان ( أَسْفَلَ سافِلِينَ ) أي تركناه ولم نلطف به الألطاف الخفية حتى تردى في أبعد مهوى ، وصار في أسفل من كل إنسان ، والمعنى أن الإنسان له شأنية هذا النحو من التردي إذا أعرض عن الإيمان والهدى واتبع الأهواء والشهوات. إِلاَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ (6) فَما يُكَذِّبُكَ بَعْدُ بِالدِّينِ (7) أَلَيْسَ ال لهُ بِأَحْكَمِ الْحاكِمِينَ (8)` },
            { text: "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ", tafsir: `بالله ورسوله واليوم الآخر ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ ) الملازمة لاجتناب السيئات ( فَلَهُمْ أَجْرٌ ) وثواب في الآخرة ( غَيْرُ مَمْنُونٍ ) أي غير مقطوع بل متواصل دائم إلى الأبد ، من « منّ » بمعنى قطع.` },
            { text: "فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ", tafsir: `أيها الإنسان ( بَعْدُ ) أي بعد هذه الحجج والآيات وبيان طرفي الإنسان صعودا وهبوطا ( بِالدِّينِ ) أي بالجزاء ، والمعنى ما الذي يسبب أن تكذب بالجزاء بعد أن عرفت الرفعة والانحطاط في الإنسان ، كما لو بين الأستاذ مضرة الرسوب ومنفعة النجاح يتساءل ما الذي يوجب للتلميذ أن يترك درسه ؟` },
            { text: "أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ", tafsir: `` }
        ]
    },
    96: { // سورة العلق
        name: "العلق",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ", tafsir: `يا رسول الله ، القرآن مصاحبا قراءتك ( بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ) فإذا قرأ كل إنسان ما يقرأ بدون اسم الله ، فأنت اقرأ مع اسم الله ، و في الحديث أن جبرئيل نزل على الرسول صلى‌الله‌عليه‌وآله‌وسلم في جبل « حراء » بمكة. فقال : « اقرأ » قال صلى‌الله‌عليه‌وآله‌وسلم : أقرأ ولست أنا بقارئ فقال عليه‌السلام : « اقرأ .. . » (1) .` },
            { text: "خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ", tafsir: `تخصيص بعد التعميم ، فإن « خلق » الأول حيث حذف متعلقة أفاد العموم ( مِنْ عَلَقٍ ) والعلق هو الدم المنجمد الذي ينقلب المني إليه ، بعد استقراره في الرحم ، وهذا هو بدء الإنسان.` },
            { text: "ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ", tafsir: `للتأكيد في القراءة ( وَرَبُّكَ ) يا رسول الله هو ( الْأَكْرَمُ ) من كل كريم ، ومن كرمه خلق الإنسان من تلك العلقة القذرة ، وأوصله إلى المقامات الرفيعة.` },
            { text: "ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ", tafsir: `الإنسان المعارف أو العلوم بسبب القلم فلو لا خلقه للقلم وتعليمه للإنسان الكتابة لبقي الإنسان في دياجير الجهل والرذيلة ، فمنه سبحانه « القراءة » ف « اقرأ .. . » ومنه الكتابة فعلم « بالقلم » ومنه البدء « من علق » ومنه الإيصال إلى الكمال.` },
            { text: "عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ", tafsir: `من أنواع العلوم والمعارف. [7] وهل يشكر الإنسان هذا الفضل العظيم لله سبحانه ، حيث أوجده من ( 1) راجع بحار الأنوار : ج 18 ص 174. كَلاَّ إِنَّ الْإِنْسانَ لَيَطْغى (6) أَنْ رَآهُ اسْتَغْنى (7) إِنَّ إِلى رَبِّكَ الرُّجْعى (8) أَ رَأَيْتَ الَّذِي يَنْ هى (9) عَبْداً إِذا صَلَّى (10) العدم إلى أن أبلغه إلى غاية الكمال الجسدي ، وقد كان جاهلا ضالا فأبلغه رتبة العلم والهدى ؟ ( كَلَّا ) لا يشكر الإنسان ، ف ( إِنَّ الْإِنْسانَ لَيَطْغى ) يتجاوز حدوده ويتكبر على ربه. [8] ل ( أَنْ رَآهُ ) أي حين رأى نفسه ( اسْتَغْنى ) في جسمه وماله ويظن أنه غني بعد ذلك فلا يحتاج إلى ربه.` },
            { text: "كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ", tafsir: `` },
            { text: "أَن رَّءَاهُ ٱسْتَغْنَىٰٓ", tafsir: `` },
            { text: "إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ", tafsir: `يا رسول الله ( الرُّجْعى ) مصدر « رجع » ، أي رجوع الخلق ، ويرجع إليه تعالى ـ أي إلى جزائه وحسابه ـ فيمن يرجع هذا الطاغي الذي طغى على الله سبحانه.` },
            { text: "أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ", tafsir: `يا رسول الله ( الَّذِي ) طغى على الله ، حتى أنه ( يَنْهى ) .` },
            { text: "عَبْدًا إِذَا صَلَّىٰٓ", tafsir: `فإنه لم يكتف بطغيانه على الله في تركه الصّلاة ـ بنفسه ـ حتى أصبح ينهى سائر العباد إذا قاموا للصلاة ؟ أ رأيت هذا الإنسان يا رسول الله ؟ وهذا استفهام لتوبيخ ذلك الشخص الناهي وتهديده. قال القمي : كان الوليد بن المغيرة ينهى الناس عن الصّلاة وأن يطاع الله ورسوله ، فنزلت هذه الآية (1) . و في رواية أخرى أن أبا جهل قال : هل يغير محمد وجهه بين أظهركم ؟ قالوا : نعم. قال : فبالذي يحلف به لئن رأيته يفعل ذلك لأطأن على رقبته ، فقيل : ها هو ذلك يصلي ، فانطلق ليطأ على رقبة الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فما جاءهم إلا وهو ينكص على عقبيه ويتقي بيديه ، فقالوا : ما لك يا أبا الحكم ؟ قال : ( 1) تفسير القمي : ج 2 ص 430. أَ رَأَيْتَ إِنْ كانَ عَلَى الْهُدى (11) أَوْ أَمَرَ بِالتَّقْوى (12) أَ رَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى (13) أَ لَمْ يَعْلَمْ بِأَنَّ اللهَ يَرى (14) كَلاَّ لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعاً بِالنَّاصِيَةِ (15) رأيت بيني وبينه خندقا من نار وهولا وأجنحة ، وقال الرسول صلى‌الله‌عليه‌وآله‌وسلم : و الذي نفسي بيده لو دنى مني لا لاختطفته الملائكة عضوا عضوا (1) ، فأنزل سبحانه « أ رأيت .. . » وكأن التقدير أ رأيت المانع عن الصّلاة ؟ وهل علمت ماذا يكون جزاؤه ؟ لبيان عظمة هذا العمل من حيث الإثم.` },
            { text: "أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ", tafsir: `يا رسول الله ( إِنْ كانَ ) العبد الذي صلى ـ وهو الرسول ـ ( عَلَى الْهُدى ) وكانت صلاته حسب أمر الله سبحانه ؟` },
            { text: "أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ", tafsir: `ذلك العبد ( بِالتَّقْوى ) والمخافة من الله سبحانه باجتناب نواهيه ؟ ماذا كان مصير ذلك له ؟ أليس مصيره إلى العذاب والنكال ؟` },
            { text: "أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ", tafsir: `يا رسول الله ( إِنْ كَذَّبَ ) ذلك الناهي ـ وهو أبو جهل أو الوليد ـ بآيات الله ورسوله ( وَتَوَلَّى ) أي أعرض عن الحق ، ما هي عاقبته ؟` },
            { text: "أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ", tafsir: `ذلك الناهي ( بِأَنَّ اللهَ يَرى ) عمله ونهيه عن الصّلاة وكذبه وتوليه ؟ ولم يعلم جزاء هذه السيئات ؟ فإنه كيف ينهى ويكفر ويعصي ، وجزاء من يفعل ذلك النار والنكال ؟` },
            { text: "كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ", tafsir: `ليس الأمر على ما توهم من أنه لا جزاء على أعماله السيئة ( لَئِنْ لَمْ يَنْتَهِ ) هذا الناهي عن أعماله وسيئاته ( لَنَسْفَعاً بِالنَّاصِيَةِ ) أي لنجرنّه بناصيته إلى النار ، من « سفع » بمعنى جذب الشيء جذبا شديدا ، « والناصية » هي شعر مقدم الرأس ، فإنه أسهل للأخذ وأوجب لانقياد المأخوذ. ( 1) بحار الأنوار : ج 9 ص 170. ناصِيَةٍ كاذِبَةٍ خاطِئَةٍ (16) فَلْيَدْعُ نادِيَهُ (17) سَنَدْعُ الزَّبانِيَةَ (18) كَلاَّ لا تُطِ عْهُ وَاسْجُدْ وَاقْتَرِبْ (19)` },
            { text: "نَاصِيَةٍ كَٰذِبَةٍ خَاطِئَةٍ", tafsir: `نسبة الكذب والخطأ إلى الناصية مجاز باعتبار علاقة الجزء والكل ، كما أن نسبة الإيمان إلى الرقبة في قوله ( رَقَبَةٍ مُؤْمِنَةٍ ) (1) كذلك والمراد أن صاحب الناصية كاذب في أقواله خاطئ في أعماله.` },
            { text: "فَلْيَدْعُ نَادِيَهُۥ", tafsir: `ذلك الإنسان الناهي ( نادِيَهُ ) أي أهل مجلسه وأصدقائه ، فإن « النادي » هو محل الاجتماع ، الذي ينادي بعضهم بعضا إليه ، ونسبة النداء إليه مجاز من باب « اسأل القرية » يعني يدعوهم لخلاصه فهل يتمكنون إنقاذه من بطش الله سبحانه ؟ قال ابن عباس : لما أتى أبو جهل رسول الله صلى‌الله‌عليه‌وآله‌وسلم انتهره الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فقال أبو جهل : أ تنتهرني يا محمد فو الله لقد علمت ما بها أحد أكثر ناديا مني ؟ فأنزل الله هذه الآية.` },
            { text: "سَنَدْعُ ٱلزَّبَانِيَةَ", tafsir: `يعني إنا ندعو الملائكة الموكلين بالنار لقبض ذلك الشخص الناهي ، وليدع هو ناديه ، حتى يظهر أينا يغلب الآخر. وهذا تهديد له بأنه لا منقذ له من بطشه سبحانه ، و « الزبانية » جمع « زبينة » وهي النفس التي تدفع ، من « الزين » بمعنى الدفع ، فإن الملائكة يدفعون المجرمين إلى النار دفعا.` },
            { text: "كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب", tafsir: `` }
        ]
    },
    97: { // سورة القدر
        name: "القدر",
        basmalaTafsir: ``,
        verses: [
            { text: "إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ", tafsir: `أي القرآن ـ المعلوم من السياق ـ والإتيان بلفظ الجمع في « إنّا » و « أنزلنا » باعتبار التعظيم ، فقد كان المتعارف أن يتكلم كل رئيس عن نفسه وعن أتباعه ، ثم أستعير « الجمع » في كل تعظيم ( فِي لَيْلَةِ الْقَدْرِ ) وهي « التاسعة عشرة » أو « الواحدة والعشرون » أو « الثالثة والعشرون » من شهر رمضان المبارك ، فقد نزل القرآن بجملته إلى البيت المعمور ـ في السماء الرابعة ـ في إحدى هذه الليالي الثلاث ، ثم نزل منجما على رسول الله صلى‌الله‌عليه‌وآله‌وسلم في ظرف ثلاث وعشرين سنة ، أو المراد أن إنزاله على قلب الرسول صلى‌الله‌عليه‌وآله‌وسلم كان في هذه الليلة ، وإنما إتيان جبرئيل به أقساطا من السماء ـ بمناسبات ـ كان في ظرف ثلاث وعشرين سنة ، وسميت الليلة ب « القدر » لتقدير أعمال العباد في هذه الليلة. وقد ورد في الأحاديث ان في هذه الليلة من كل سنة تنزل أفواج من الملائكة بالتقديرات لتلك السنة ، إلى الإمام الحي من الأئمة الإثني عشر عليهم‌السلام بعد الرسول صلى‌الله‌عليه‌وآله‌وسلم فيعلم الإمام بما قدر الله سبحانه للخلائق من الآجال والأرزاق والأعمال وسائر الأمور المرتبطة بهم (1) ، وهذا لا يعني أنهم كالرسول صلى‌الله‌عليه‌وآله‌وسلم في نزول الوحي ، فقد نزل جبرئيل على مريم وليست رسولا ، بل هو تشريف من الله سبحانه للإمام الذي هو خليفة في أرضه بعد الرسول ، وفي دورنا تنزل الملائكة بالتقديرات ـ في ليلة القدر ـ على الإمام المهدي المنتظر « عجل الله فرجه » .` },
            { text: "وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ", tafsir: `يا رسول الله ، أو أيها السامع ( ما ) هي ( لَيْلَةُ الْقَدْرِ ) ؟ وهذا لتعظيم شأنها. ( 1) راجع بحار الأنوار : ج 82 ص 52. لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ (3) تَنَزَّلُ الْمَلائِكَةُ وَالرُّوحُ فِيها بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ (4) سَلامٌ هِي َ حَتَّى مَطْلَعِ الْفَجْرِ (5)` },
            { text: "لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ", tafsir: `يعني أن الأعمال الصالحة في ليلة القدر خير من العمل الصالح في ألف شهر ـ التي هي أكثر من ثمانين سنة ـ فإن الأزمان إنما تفضل بعضها على بعض بما يقع فيها من الأعمال أو المعنى أن تلك الليلة التي نزل فيها القرآن ، خير من ألف شهر لما حدث فيه من أمر عظيم هو نزول القرآن.` },
            { text: "تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ", tafsir: `أصله « تتنزل » حذفت إحدى تائيه على القاعدة ـ كما سبق ـ ( الْمَلائِكَةُ وَالرُّوحُ ) وهو ملك عظيم ، أو جبرئيل عليه‌السلام ( فِيها ) أي في تلك الليلة ( بِإِذْنِ رَبِّهِمْ ) فإن الله يأذن لهم في النزول على الرسول والإمام لبيان مقدرات العباد في تلك السنة ( مِنْ كُلِّ أَمْرٍ ) فقد جاء جبرئيل وسائر الملائكة إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم في تلك الليلة ومعهم كل أمر مربوط بالأرض من الهداية والإرشاد ، والتنظيم والتقنين والسعادة والخير ؟ وكذلك يأتون في كل سنة إلى الإمام الحي بذلك كله.` },
            { text: "سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ", tafsir: `` }
        ]
    },
    98: { // سورة البينة
        name: "البينة",
        basmalaTafsir: ``,
        verses: [
            { text: "لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ", tafsir: `يعني اليهود والنصارى والمجوس ، والوصف ليس للتصنيف بل للبيان ، فإن كل أهل الكتاب قد كفروا بنسبتهم إلى الله الولد والشريك وتوصيفهم له بما لا يليق بجلال شأنه ( وَ ) من ( الْمُشْرِكِينَ ) الذين أشركوا بالله وعبدوا الأصنام معه ( مُنْفَكِّينَ ) أي منتهين عن كفرهم ، من « انفك » بمعنى زال عنه ، وابتعد ( حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ ) أي الحجة الظاهرة ـ وهو القرآن الكريم ، والرسول العظيم ـ إذ لا مجال لهم في عرفان الحقائق بعد ما حرّفوا كتبهم وبدلوا دينهم. [3] ثم بين المراد بالبينة بقوله : ( رَسُولٌ مِنَ اللهِ ) أي من طرفه سبحانه ( يَتْلُوا ) ويقرأ عليهم ( صُحُفاً مُطَهَّرَةً ) هي صحائف القرآن الحكيم التي طهرت عن الكفر والشرك ونسبة ما لا يليق إلى الله وإلى أنبيائه ، فإن النبي وإن كان يتلو عن ظهر القلب لكنه كان يقرأ عن اللوح المحفوظ عكس كتاب العهدين.` },
            { text: "رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً", tafsir: `` },
            { text: "فِيهَا كُتُبٌ قَيِّمَةٌ", tafsir: `أي في تلك الصحف ( كُتُبٌ قَيِّمَةٌ ) « الكتاب » يستعمل بمعنى الموضوع ، كما يقال : كتاب الصلاة ، وكتاب الحج ، يراد موضوعهما ـ ولذا نرى كتاب الصلاة ، مثلا في ضمن كتاب « شرائع الإسلام للمحقق » ، أو أن الكتاب بمعنى المكتوب ، وهو في الصحيفة ، يعني أن تلك الصحف تشتمل على موضوعات ذات قيمة وثمن ، أو بمعنى وَما تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتابَ إِلاَّ مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّنَةُ (4) وَما أُمِرُوا إِلاَّ لِيَعْبُدُوا اللهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكاةَ وَذلِكَ دِينُ الْقَيِّمَةِ (5) إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ ذات استقامة ، فإن القيمة بمعنى المستمرة في جهة الصواب.` },
            { text: "وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ", tafsir: `أي أعطوا الكتاب السماوي ( إِلَّا مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّنَةُ ) أي الحجة الواضحة ، والمعنى أن أهل الكتاب إنما اختلفوا ـ في أمر الرسول أو أمر دينهم السابق بأن صار لكل فئة مذهب وطريقة ـ بعد أن تمت عليهم الحجة وعرفوا الصواب ، وإنما اختلفوا بغيا وحسدا.` },
            { text: "وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ", tafsir: `الحال أن الله لم يأمرهم إلا بعبادته واتباع طريقته ، فإنهم ( ما أُمِرُوا إِلَّا لِيَعْبُدُوا اللهَ ) وحده في حال كونهم ( مُخْلِصِينَ لَهُ الدِّينَ ) أي يخلصون الطريقة لله سبحانه ، بلا زيادة أو نقصان ، أو شرك أو انحراف ، في حال كونهم ( حُنَفاءَ ) جمع حنيف ، أي مائلين عن الأديان الباطلة والطرائق الزائفة ، من « حنف » بمعنى مال ( وَيُقِيمُوا الصَّلاةَ ) أي يداوموا على إقامة الصّلاة ( وَيُؤْتُوا الزَّكاةَ ) أي يعطوها ، والمراد بها إما مطلق الإعطاء ، أو الزكاة المفروضة. فقد فرضت الزكاة في الأديان السابقة ـ ( وَذلِكَ ) الدين المشتمل على هذه الأمور المذكورة ( دِينُ الْقَيِّمَةِ ) أي دين الكتب القيمة ـ التي تقدم ذكرها ـ بمعنى أنه الدين المذكور في تلك الكتب.` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ", tafsir: `استمروا على كفرهم فلم يؤمنوا وَالْمُشْرِكِينَ فِي نارِ جَهَنَّمَ خالِدِينَ فِيها أُولئ ِكَ هُمْ شَرُّ الْبَرِيَّةِ (6) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ أُولئِكَ هُمْ خَيْرُ الْبَرِيَّةِ (7) جَزاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها أَبَداً رَضِيَ اللهُ عَنْهُمْ وَرَضُوا عَنْهُ ذلِكَ لِمَنْ خَشِيَ رَبَّهُ (8) بالرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَ ) من ( الْمُشْرِكِينَ ) بأن استمروا في شركهم يكونون ( فِي نارِ جَهَنَّمَ ) في الآخرة حال كونهم ( خالِدِينَ فِيها ) أي في النار إلى الأبد ( أُولئِكَ هُمْ شَرُّ الْبَرِيَّةِ ) أي شر الخلق ، فإن البرية هي الخليقة ، من برأ بمعنى خلق وأنشأ.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ", tafsir: `بالله ورسوله واليوم الآخر ( وَعَمِلُوا الصَّالِحاتِ ) أي الأعمال الصالحة ، الملازمة لعدم الإتيان بالأعمال الفاسدة ( أُولئِكَ هُمْ خَيْرُ الْبَرِيَّةِ ) أي الأفضل من جميع الخلق ، وفي مقابلهم من آمن وعصى ، فإنه ليس بذلك الشر ولا بذلك الخير.` },
            { text: "جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ", tafsir: `` }
        ]
    },
    99: { // سورة الزلزلة
        name: "الزلزلة",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا", tafsir: `أي حركت تحركها الشديد ، واضطربت اضطرابا عظيما.` },
            { text: "وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا", tafsir: `كل ما فيها من الأشياء الثقيلة ، من معادن ودفائن وأموات وأشباه ذلك ، فإنها تلقيها على ظهرها عند قيام الساعة.` },
            { text: "وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا", tafsir: `متعجبا من هذه الحوادث : ( ما لَها ) أي ما للأرض تتزل زل وتضطرب وتخرج ما في بطنها ؟!` },
            { text: "يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا", tafsir: `أي في ذلك اليوم ـ وهو يوم القيامة ـ ( تُحَدِّثُ ) الأرض ( أَخْبارَها ) ورد عن الرسول صلى‌الله‌عليه‌وآله‌وسلم أنه قال : أ تدرون ما أخبارها ؟ قالوا : الله ورسوله أعلم. قال : أخبارها أن تشهد على كل عبد بما عمل على ظهرها. [6] كل ذلك الزلزال والإخراج والحديث يصدر من الأرض بسبب أن ( رَبَّكَ ) يا رسول الله ( أَوْحى لَها ) أي للأرض بأن تعمل ذلك ، والسماء والأرض مطيعتان لله سبحانه فيما يأمر ، كما قال سبحانه ( قالَتا أَتَيْنا طائِعِينَ ) (1) .` },
            { text: "بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا", tafsir: `` },
            { text: "يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَٰلَهُمْ", tafsir: `أي في ذلك اليوم ( يَصْدُرُ النَّاسُ ) أي يرجع الناس من قبورهم إلى المحشر ( أَشْتاتاً ) جمع « شتيت » أي متفرقين ، بعضهم ( 1) فصلت : 12. لِيُرَوْا أَعْمالَهُمْ (6) فَمَنْ يَعْمَلْ مِثْقالَ ذَرَّةٍ خَيْراً يَرَهُ (7) وَمَنْ يَعْمَلْ مِث ْقالَ ذَرَّةٍ شَرًّا يَرَهُ (8) لعاقبة حسنة وبعضهم لعاقبة سيئة ( لِيُرَوْا ) ـ على البناء للمفعول ـ أي حتى يريهم الله ( أَعْمالَهُمْ ) التي عملوها ويجازي كل على عمله.` },
            { text: "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ", tafsir: `في الدنيا ( مِثْقالَ ذَرَّةٍ ) أي بقدر ثقل ذرة ـ وهي الهباءة التي ترى في الشمس إذا دخلت من الكوة في المحل المظلم ـ ( خَيْراً يَرَهُ ) أي يرى جزاء ذلك الخير ، في ذلك اليوم.` },
            { text: "وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ", tafsir: `` }
        ]
    },
    100: { // سورة العاديات
        name: "العاديات",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلْعَٰدِيَٰتِ ضَبْحًا", tafsir: `أي قسما بالأفراس التي تعدو في سبيل الله للجهاد ( ضَبْحاً ) أي تضبح ضبحا ، « والضبح » هو صوت الجوف الذي يسمع من الخيل حين تعدو.` },
            { text: "فَٱلْمُورِيَٰتِ قَدْحًا", tafsir: `أي قسما بالموريات ، والفاء للترتيب في الكلام أي الخيل التي تورى النار وتظهرها ، بوطء حوافرها على الأحجار ( قَدْحاً ) مثل نار الزناد إذا قدح ، تقدح قدحا أي تضرب ضربا يقال أورى القادح النار : إذا أظهرها. [4] فقسما بالمغيرات أي الأفراس التي أغارت على العدو ( صُبْحاً ) بعد أن سار المجاهدون ليلا ، حتى إذا أصبحوا أغاروا.` },
            { text: "فَٱلْمُغِيرَٰتِ صُبْحًا", tafsir: `` },
            { text: "فَأَثَرْنَ بِهِۦ نَقْعًا", tafsir: `تلك الأفراس ( بِهِ ) أي بذلك المكان ـ المعلوم من السياق ـ ( نَقْعاً ) أي غبارا ، يعني أن تلك الخيل أثارت بذلك المكان الغبار الكثير لمطاردتها الأعداء ، و « نون » جمع المؤنث يأتي للعاقلة وغير العاقلة ـ كما سبق ـ .` },
            { text: "فَوَسَطْنَ بِهِۦ جَمْعًا", tafsir: `تلك الأفراس ( بِهِ ) أي بذلك المكان ( جَمْعاً ) أي صرن في وسط ذلك المكان ، حتى فتحوا على العدو ، إذ حصلوا في وسطهم وأحدثوا الفوضى والاضطراب فيهم على حين غرة ، وهذه الآيات نزلت في « غزوة ذات السلاسل » . وهي كما في كتاب « قادة الإسلام » (1) اشتركت قبائل من « لخم » و « جذام » و « بلقين » و « بهر » و ( 1) للمؤلف. « بلى » و « طي » و « عذرة » وغيرها في حرب « مؤتة » وساعدت الكفار على المسلمين ، وبعد وقعة « مؤتة » تجمعت قوى هؤلاء لمحاربة المسلمين وكان عددها اثني عشر ألف مقاتل ، فأراد الرسول صلى‌الله‌عليه‌وآله‌وسلم أن يؤدبهم ويأخذ بثأر المسلمين الذين استشهدوا في « مؤتة » ، فجهز جيشا من أربعة آلاف نفر ، برئاسة « أبي بكر » وأمرهم بالذهاب إلى الكفار ومقاتلتهم ، وتوجه أبو بكر إلى تلك المنطقة ، فلما رأوه خرجوا إليه وحذروه من محاربتهم ، فخاف أبو بكر ورجع ، واغتاظ الرسول صلى‌الله‌عليه‌وآله‌وسلم من رجوعه ، ثم أمر الرسول صلى‌الله‌عليه‌وآله‌وسلم « عمر » على الجيش فأرسلهم وحذرهم من الجبن ، لكن عمر جبن كأخيه من قبل ، « وآب بخفي حنين » ثم أمر الرسول « عمرو بن العاص » وأرسلهم لكنهم أيضا رجعوا حينئذ عقد الرسول صلى‌الله‌عليه‌وآله‌وسلم اللواء بقيادة الإمام أمير المؤمنين عليه‌السلام ووصاه بما أوصى به أولئك ثم قال الرسول صلى‌الله‌عليه‌وآله‌وسلم : أنه لا بد وأن يفتح الله على يديك .. . جاء الإمام عليه‌السلام حتى وصل إلى قرب معسكر الكفار بحيث يرونه ويراهم ، فانحاز من معسكرهم مائتا رجل ، وكلموا الإمام فدعاهم الإمام إلى الإسلام ، لكنهم أبوا وقالوا : إنا لنقتلكم جميعا وضربوا الموعد يوم غد ، وانصرفوا إلى معسكرهم ينتظرون غدا. أمر الإمام جيشه أن يستعدوا ، فأخذوا كامل استعدادهم في الليل فلما أصبح الصباح وصلوا صلاة الصبح ، أمر الإمام الجيش بالهجوم على القوم ، فهجم جيش المسلمين يقدمهم الإمام عليه‌السلام على الكفار وهم نائمون إلا قليلا منهم ، وأولئك القليل لم يكونوا مستعدين للقتال فانهزموا أمام الجيش الإسلامي ، وقد أكثر فيهم الجيش من إِنَّ الْإِنْسانَ لِرَبِّهِ لَكَنُودٌ (6) وَإِنَّهُ عَلى ذلِكَ لَشَهِيدٌ (7) وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ (8) أَ فَلا يَعْلَمُ إِذا بُعْثِرَ ما فِي الْقُبُورِ (9) و َحُصِّلَ ما فِي الصُّدُورِ (10) القتل والأسر ، ولم تطلع الشمس إلا والجيش الإسلامي يحملون الأسرى والغنائم ، ليعودوا إلى المدينة منتصرين ، واستقبل الرسول صلى‌الله‌عليه‌وآله‌وسلم والمسلمون الإمام عليه‌السلام وجيشه ، وهنا نزلت سورة العاديات (1) . [7] قسما بتلك الأقسام المتقدمة ( إِنَّ الْإِنْسانَ لِرَبِّهِ لَكَنُودٌ ) أي لكفور ، ومنه الأرض الكنود التي لا تنبت شيئا ، والأصل فيه منع الحق.` },
            { text: "إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌ", tafsir: `` },
            { text: "وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ", tafsir: `أي الإنسان ( عَلى ذلِكَ ) الكفر ( لَشَهِيدٌ ) أي يشهد بذلك ، فإن الإنسان يعلم ما له وما عليه ، وإن لم يعترف بما عليه ، أو المعنى أنه يشهد بذلك يوم القيامة ، حيث يختم على أفواههم وتكلمنا أيديهم وأرجلهم بما كانوا يعملون.` },
            { text: "وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ", tafsir: `أي الإنسان ( لِحُبِّ الْخَيْرِ لَشَدِيدٌ ) فإنه شديد في حب كل خير لنفسه ، هذا طبع الإنسان ، لو لم يخرجه الإيمان.` },
            { text: "أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ", tafsir: `الإنسان ( إِذا بُعْثِرَ ما فِي الْقُبُورِ ) أي بعث الموتى وأخرجوا من قبورهم ، منتشرين مبعثرين هنا وهناك ؟` },
            { text: "وَحُصِّلَ مَا فِى ٱلصُّدُورِ", tafsir: `بأن ظهرت نوايا الناس وما أضمروه من خير وشر ؟ ليجازي كل حسب ما نواه وأضمره وعمله وأتى به. ألا ( 1) تفسير فرات الكوفي : ص 591. إِنَّ رَبَّهُمْ ب ِهِمْ يَوْمَئِذٍ لَخَبِيرٌ (11) يعلم ماذا يكون مصيره يومذاك ؟ فكيف يعصي ويكند ؟ كما تقول لمن يعصي : ألا تعترف بالحساب ؟ تريد بذلك تهديده.` },
            { text: "إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ", tafsir: `` }
        ]
    },
    101: { // سورة القارعة
        name: "القارعة",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلْقَارِعَةُ", tafsir: `هي من أسماء القيامة ، لأنها تقرع القلوب بالخوف وتقرع الناس بالعذاب ، وتقرع الجبال فتجعلها دكا دكا.` },
            { text: "مَا ٱلْقَارِعَةُ", tafsir: `أي ما هي القارعة ؟ وذلك لتفخيم شأنها وتعظيم أمرها ، و « القارعة » الأولى مبتدأ ، و « ما » مبتدأ ثان ، و « القارعة » الثانية خبر « ما » ، والجملة خبر « قارعة » الأولى.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ", tafsir: `أيها الإنسان أو أيها الناس ( مَا الْقارِعَةُ ) ؟ هذه الجملة لتفخيم شأنها ، يعني أنها من الهول بحيث لا تعلمها ولا تدركها ، إلا بعد أن تراها.` },
            { text: "يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ", tafsir: `وهو الغوغاء من الجراد الذي ينفرش ويركب بعضها فوق بعض ( الْمَبْثُوثِ ) أي المنتشر ، فإن الناس يكونون مثل الفراش في الكثرة والاضطراب والانتشار.` },
            { text: "وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ", tafsir: `أي الصوف الملون ( الْمَنْفُوشِ ) أي المندوف ، فإنها تقلع عن أماكنها وتحطم حتى تكون كالصوف ذي الألوان الخفيف اليسير ، وألوانها ، لاختلاف ألوان الجبال فإنها بيض وحمر وسود وغيرها.` },
            { text: "فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ", tafsir: `أي رجحت حسناته وكثرت والإتيان بالجمع فَهُوَ فِي عِيشَةٍ راضِيَةٍ (7) وَأَمَّا مَنْ خَفَّتْ مَوازِينُهُ (8) فَأُمُّهُ هاوِيَةٌ (9) وَما أَدْراكَ ما هِيَهْ (10) نارٌ حامِيَةٌ (11) لأن لكل عمل حسن ميزان فميزان للصلاة ، وميزان لبر الوالدين ، وهكذا. وهل المراد بالميزان هو المعهود في الدنيا ـ كما هو الظاهر ـ أو غيره احتمالان ؟` },
            { text: "فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ", tafsir: `أي عيشة ذات رضى يرضاها صاحبها ونسبة الرضى إليها ـ مع كون الراضي هو الذي يعيش ـ مجاز.` },
            { text: "وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ", tafsir: `بأن قلت حسناته ، وكثرت سيئاته.` },
            { text: "فَأُمُّهُۥ هَاوِيَةٌ", tafsir: `أي مأواه ( هاوِيَةٌ ) أي جهنم ، والمعنى أن محله النار ، فكما أن الولد يأوي إلى أمه كذلك يأوي العاصي إلى جهنم ، وإنما سميت بالهاوية لهوى الشخص فيها.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا هِيَهْ", tafsir: `يا رسول الله ، أو أيها الإنسان ( ما هِيَهْ ) ؟ هذا تفخيم لعذاب النار ، حتى أن الرسول ـ أو السامع ـ لا يدرك حقيقتها وتفصيلها لهولها ، والهاء للسكت. [12] إنها ( نارٌ حامِيَةٌ ) قد بلغت آخر شدتها في الحرارة والالتهاب. (102)` },
            { text: "نَارٌ حَامِيَةٌۢ", tafsir: `` }
        ]
    },
    102: { // سورة التكاثر
        name: "التكاثر",
        basmalaTafsir: ``,
        verses: [
            { text: "أَلْهَىٰكُمُ ٱلتَّكَاثُرُ", tafsir: `أي أشغلكم عن طاعة الله وعبادته ، أيها الناس ( التَّكاثُرُ ) بالأموال والأولاد والأمور المرتبطة بالدنيا ، والتفاخر بكثرتها يقال تكاثر إذا تباهي بالكثرة.` },
            { text: "حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ", tafsir: `أي ذهبتم إلى القبور لزيارتها ، فإن هناك ينتبه الإنسان إلى فناء الدنيا ، وعدم الفائدة في التباهي والتفاخر بكثرة الأمور المرتبطة بها ، أو المعنى حتى أدركتم الموت ، وكني عن ذلك بزيارة المقابر دلالة على عدم بقاء الإنسان فيها أيضا ، فإنه ينتقل منها إلى الدار الآخرة.` },
            { text: "كَلَّا سَوْفَ تَعْلَمُونَ", tafsir: `ليس الأمر كما أنتم عليه من التكاثر ( سَوْفَ تَعْلَمُونَ ) عاقبة الاشتغال بالدنيا ، والغفلة عن الآخرة ، وهذا تهديد لهم.` },
            { text: "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ", tafsir: `لترتب الكلام ( كَلَّا ) ليس الأمر على ما أنتم عليه ( سَوْفَ تَعْلَمُونَ ) كرّر للتكريز والإيحاء بالارتداع عن التكاثر لو خامة عاقبته.` },
            { text: "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ", tafsir: `ليس الأمر كما زعمتم ( لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ ) أي علما يقينيا ، بحيث تتيقنون بالآخرة ـ لا علما استدلاليا فقط ـ أي لو تعلمون لعلمتم أن التباهي والتكاثر لا ينبغي ، وإنما الاشتغال بالآخرة هو الأمر اللازم.` },
            { text: "لَتَرَوُنَّ ٱلْجَحِيمَ", tafsir: `رؤية بالقلوب ، حتى كأنكم تشاهدونها ، فتخافون من الاشتغال عن أمرها ، بما لا فائدة فيه من التباهي والتفاخر. ثُمَّ لَتَرَوُنَّها عَيْنَ الْيَقِينِ (7) ثُمَّ لَتُسْئَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ (8)` },
            { text: "ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ", tafsir: `بعد كثرة التفكير في الجحيم ورؤيتها بالقلب ( لَتَرَوُنَّها ) أي الجحيم ( عَيْنَ الْيَقِينِ ) أي اليقين الذي هو كالمعاينة ، كما قال الإمام أمير المؤمنين عليه‌السلام « فهم والجنة كمن قد رآها فهم فيها منعمون ، وهم والنار كمن قد رآها فهم فيها معذبون » فأولى المراتب العلم الاستدلالي ، ثم ذوق القلب باليقين الصادق ثم استيلاء اليقين على القلب حتى كأن الإنسان يشاهد الشيء المعلوم.` },
            { text: "ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ", tafsir: `` }
        ]
    },
    103: { // سورة العصر
        name: "العصر",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلْعَصْرِ", tafsir: `قسما بالعصر ، أي عصر النبوة ، أو عصر الدهر ، أو عصر الحجة عليه‌السلام ، أو العصر مقابل الصبح ، كما حلف سبحانه ب « الضحى » وما أشبه ـ وقد سبق الوجه في هذه الأقسام ـ .` },
            { text: "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ", tafsir: `بطبيعته ( لَفِي خُسْرٍ ) أي خسارة مستمرة ، إذ يتدرج نحو الفناء ، كما تتدرج أخلاقه في الانحطاط ، فإن الإنسان كلما دخل في الدنيا أكثر ، زاد تكالبه ورذائله ، بالإضافة إلى أن كل ساعة تذهب ولم يعمل الإنسان فيها صالحا كان خاسرا ، إذ ذهب من رأس ماله ـ الذي تمكن به من تحصيل أرقى الدرجات ـ هباء هدرا ، ولو لم يحصل على المعصية في تلك الساعة فرضا.` },
            { text: "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ", tafsir: `` }
        ]
    },
    104: { // سورة الهمزة
        name: "الهمزة",
        basmalaTafsir: ``,
        verses: [
            { text: "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ", tafsir: `هي كلمة تقال لبيان سوء حال المقولة فيه ( لِكُلِّ هُمَزَةٍ ) هو الكثير الطعن على الناس بغير حق العائب لهم ، وأصل الهمز الكسر ، فكأن العائب يكسر الشخص ويهدم شوكته ( لُمَزَةٍ ) هو المغتاب للناس ، وهما وصفان بمعنى « همّاز » و « لمّاز » .` },
            { text: "ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ", tafsir: `من هنا وهناك ( وَعَدَّدَهُ ) أي أحصاه ، ليرى كم زاد ، وهذه صورة للإنسان الشره المنحط النفس الذي يدأب في جمع المال ، ويعيب الناس كلهم بلا استثناء.` },
            { text: "يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ", tafsir: `أي يظن ( أَنَّ مالَهُ أَخْلَدَهُ ) أي يقيه في الدنيا ويمنعه من الحوادث ، فإن كل حادث ينوبه يدفع بالمال رشوة ، أو إنفاقا لدفع جريمة عملها ، أو مرض جاء إليه ، أو ما أشبه. والمراد أن فعله فعل من يحسب ذلك وإن كان كل إنسان يعلم بالموت ، ويدري أنه لا مفر له منه.` },
            { text: "كَلَّا لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ", tafsir: `ليس الأمر على ما توهم ، من أنه ذو مال مرح إلى الأبد ، وأنه خالد بماله ( لَيُنْبَذَنَ ) أي يطرحن هذا الهمزة اللمزة طرحا بدون مبالاة واعتناء ( فِي الْحُطَمَةِ ) اسم من أسامي جهنم ، سميت بها لأنها تحطم كل شيء وتكسره فتحطم النار كيانه وكبرياءه.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ", tafsir: `أيها الإنسان ، أو أيها الرسول صلى‌الله‌عليه‌وآله‌وسلم ( مَا الْحُطَمَةُ ) ؟ وهذه لتفخيم شأنها وأنها لا تدرك إلا إذا شاهدها الإنسان. نارُ اللهِ الْمُوقَدَةُ (6) الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ (7) إِنَّها عَلَيْهِمْ مُؤْصَدَةٌ (8) فِي عَمَدٍ مُم َدَّدَةٍ (9) [7] ثم جاء البيان لها بقوله : هي ( نارُ اللهِ الْمُوقَدَةُ ) وكم يقدر الإنسان عظمة النار التي يوقدها ويؤججها الله سبحانه الذي هو أقدر القادرين للنكال والعقاب.` },
            { text: "نَارُ ٱللَّهِ ٱلْمُوقَدَةُ", tafsir: `` },
            { text: "ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ", tafsir: `جمع فؤاد ، أي تشرف على القلوب لتحرق مكان انبعاث السخرية وحب المال وتعداده بلا إنفاقه في سبيل الله وفي وجوه الخير.` },
            { text: "إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ", tafsir: `أي الحطمة ( عَلَيْهِمْ ) أي على هؤلاء المجرمين ( مُؤْصَدَةٌ ) فتغلق أبوابها عليهم لييئسوا من الخروج ، من أوصد الباب : بمعنى أغلقه.` },
            { text: "فِى عَمَدٍ مُّمَدَّدَةٍۭ", tafsir: `` }
        ]
    },
    105: { // سورة الفيل
        name: "الفيل",
        basmalaTafsir: ``,
        verses: [
            { text: "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ", tafsir: `أي ألم تسمع يا رسول الله ، أو أيها السامع ( كَيْفَ فَعَلَ رَبُّكَ ) من العذاب والنكال ( بِأَصْحابِ الْفِيلِ ) الذين جاؤوا به لهدم الكعبة ؟` },
            { text: "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ", tafsir: `الله ( كَيْدَهُمْ ) الذي كادوا لهدم البيت واحتالوا لإطفاء نور الله ( فِي تَضْلِيلٍ ) أي في تضييع وإبطال ، فكأن كيدهم عوض أن يهدي إلى مقصدهم أضلهم وأورث هلاكهم ودمارهم.` },
            { text: "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ", tafsir: `الله ( عَلَيْهِمْ طَيْراً ) يسمى ( أَبابِيلَ ) وهو الخطاف أو بمعنى جماعات ، فإن أبابيل في اللغة بمعنى جماعات في تفرقة أي جماعة جماعة.` },
            { text: "تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ", tafsir: `تلك الأسراب من الطير ـ فإن المراد بالطير الجنس ( بِحِجارَةٍ مِنْ سِجِّيلٍ ) أي تقذفهم بأحجار صغار صلبة هي من طين متحجر ، وهو معرّب « سنك كل » ، وذلك أشد وأصلب وأوجع إذا أصاب الإنسان.` },
            { text: "فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ", tafsir: `` }
        ]
    },
    106: { // سورة قريش
        name: "قريش",
        basmalaTafsir: ``,
        verses: [
            { text: "لِإِيلَٰفِ قُرَيْشٍ", tafsir: `من « آلف » نقيض « أوحش » يعني من أجل أن جعل الله الحرم وطرقه آمنا حتى ألف قريش أن يذهب إلى الشام وإلى اليمن ، في أمن ودعة ، بلا استيحاش وخوف.` },
            { text: "إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ", tafsir: `أي رواحهم في الشتاء إلى اليمين لأجل التجارة ( وَالصَّيْفِ ) أي رواحهم في الصيف إلى الشام لأجل التجارة ، وهذا توضيح لقوله « لإيلاف قريش » .` },
            { text: "فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ", tafsir: `هذا متعلق « لإيلاف » أي ليعبد قريش ( رَبَّ هذَا الْبَيْتِ ) إله الحرم لأجل ما صنع لهم من الألفة والأمن ، حتى ألفوا السفر في كل سنة بلا خوف ولا وحشة ، فقوله « لإيلاف » متعلق بقوله « فليعبدوا » . [5] ثم بين بعض أوصافه سبحانه مما تخصهم بقوله : الرب ( الَّذِي أَطْعَمَهُمْ ) أي طعم ( مِنْ جُوعٍ ) بما سبب لهم من الأرزاق في رحلتي الشتاء والصيف ( وَآمَنَهُمْ مِنْ خَوْفٍ ) بما هيأ لهم حرما آمنا ، لا يلقون فيه إلا الأمن حيث يختطف الناس من حولهم ، ومعنى « من » : بعد ، أي أطعمهم بعد الجوع ، وآمنهم بعد الخوف ، أو بمعنى « من حيث » أي من هاتين الناحيتين ـ وهذا أقرب بالنسبة إلى الموضوع ـ قال القمي : نزلت في قريش ، لأنه كان معاشهم من الرحلتين رحلة في الشتاء إلى اليمن ورحلة في الصيف إلى الشام ، وكانوا يحملون من مكة الأدم واللب وما يقع من ناحية البحر من الفلفل وغيره ، فيشترون من الشام الثياب والدرمك « وهو دقيق الحبوب » والحبوب ، وكانوا يتألفون في طريقهم ويثبتون في الخروج في كل خرجة رئيسا من رؤساء قريش ، وكان معاشهم من ذلك ، فلما بعث الله نبيه محمد صلى‌الله‌عليه‌وآله‌وسلم استغنوا عن ذلك ، لأن الناس وفدوا على رسول الله صلى‌الله‌عليه‌وآله‌وسلم وحجوا إلى البيت (1) . ( 1) تفسير القمي : ج 2 ص 444. (107)` },
            { text: "ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ", tafsir: `` }
        ]
    },
    107: { // سورة الماعون
        name: "الماعون",
        basmalaTafsir: ``,
        verses: [
            { text: "أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ", tafsir: `يا رسول الله ، أو أيها الرائي ( الَّذِي يُكَذِّبُ بِالدِّينِ ) أي بيوم القيامة. فإن « الدين » بمعنى الجزاء ، أو المراد بدين الإسلام وهذا استفهام تعجبي. يعني كيف أنه يكذب مع كثرة الآيات الدالة على صحة الدين ووقوعه.` },
            { text: "فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ", tafsir: `الإنسان المكذب بالدين ، هو ( الَّذِي يَدُعُّ الْيَتِيمَ ) « الدع » هو الدفع بشدة ، أي يدفع اليتيم فلا يحسن إليه ، فإن التكذيب بالدين يلازم الأعمال البشعة القاسية.` },
            { text: "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ", tafsir: `أي لا يحث الناس على إطعام الفقراء الذين أسكنهم الفقر عن الحركة والعمل ، و « الحض » وإن لم يكن واجبا ـ في غير مورد الأمر بالمعروف وما أشبه ـ إلا أن ذلك دليل القساوة ونضوب معين الفضيلة من القلب ، مما لا يكون إلا من ملازمات الكفر ، وقد ورد إن بعض كفار قريش كان كذلك إذا جاءه يتيم يطلب رفده طرده بقساوة ، وهكذا كان بالنسبة إلى المساكين. [5] وإذا كان « دعّ اليتيم » و « عدم الحض على طعام المساكين » موجبا للذم والتوبيخ ، فمن يعمل باسم الإسلام وهو بعيد عنه كان أولى بالذم والتوبيخ ، إذ المنافق أسوأ حالا من الكافر ( فَوَيْلٌ لِلْمُصَلِّينَ ) .` },
            { text: "فَوَيْلٌ لِّلْمُصَلِّينَ", tafsir: `` },
            { text: "ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ", tafsir: `أي غافلون غير مبالين بها إذ عدم المبالاة يلازم السهو. الَّذِينَ هُمْ يُراؤُنَ ( 6) وَيَمْنَعُونَ الْماعُونَ (7)` },
            { text: "ٱلَّذِينَ هُمْ يُرَآءُونَ", tafsir: `فإذا صلوها صلوا للرياء لا لله سبحانه. وقال بعض : إن المعنى أنهم إن لم يكن أحد لم يصلوا ، وإن كان أحد صلوها ليراؤوه.` },
            { text: "وَيَمْنَعُونَ ٱلْمَاعُونَ", tafsir: `` }
        ]
    },
    108: { // سورة الكوثر
        name: "الكوثر",
        basmalaTafsir: ``,
        verses: [
            { text: "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ", tafsir: `يا رسول الله ( الْكَوْثَرَ ) مشتق من الكثرة ، بمعنى الخير الكثير. قالوا : إن السورة نزلت في العاص بن وائل السهمي ، وذلك أنه رأى رسول الله صلى‌الله‌عليه‌وآله‌وسلم يخرج من المسجد فالتقيا عند باب بني سهم وتحدث مع الرسول ، وصناديد قريش جالسون ، فلما أن دخل قالوا له مع من كنت تتحدث ؟ قال : مع الأبتر ـ يعني الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ ، وقد كانت قريش تسمي من لا ولد له « أبتر » من البتر بمعنى القطع ، كأنه مقطوع ليس له ولد حتى يبقى ذكره ، وقد كان مات « عبد الله » ابن رسول الله من خديجة عليها‌السلام ، فنزلت هذه السورة (1) ، ولذا كان من جملة الأقوال في معنى كوثر أن المراد بها « فاطمة » عليها‌السلام التي سببت كثرة النسل للرسول صلى‌الله‌عليه‌وآله‌وسلم ، وحيث إن « الكوثر » بمعنى الخير الكثير ، وهو عام ، كان شاملا للنبوة والعلم ، والنسل ، وحوض الكوثر في الآخرة ، وغيرها من سائر المعاني التي يشملها لفظ « الكوثر » بعمومه.` },
            { text: "فَصَلِّ لِرَبِّكَ وَٱنْحَرْ", tafsir: `يا رسول الله ( لِرَبِّكَ ) شكرا على هذه النعمة العظمى. ( وَانْحَرْ ) الإبل لإطعام الناس ، فإن الله سبحانه يحب إطعام الطعام ، أو المراد ارفع يديك إلى نحرك عند التكبير ـ كما ورد (2) ـ فإن في ذلك خضوعا لله سبحانه ، يلائم الشكر على نعمته بإعطائه الكوثر.` },
            { text: "إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ", tafsir: `` }
        ]
    },
    109: { // سورة الكافرون
        name: "الكافرون",
        basmalaTafsir: ``,
        verses: [
            { text: "قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ", tafsir: `يا رسول الله ، مخاطبا للكافرين ( يا أَيُّهَا الْكافِرُونَ ) النزول وإن كان خاصا لكن المراد عام لكل كافر معاند لا يتزحزح عن كفره وطغيانه.` },
            { text: "لَآ أَعْبُدُ مَا تَعْبُدُونَ", tafsir: `أنا ( ما تَعْبُدُونَ ) أنتم من الأصنام والأوثان ، والمعنى لا أعبد في الحال ما تعبدونه الآن.` },
            { text: "وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ", tafsir: `أي تعبدون ( ما أَعْبُدُ ) إذ عاندتم وكابرتم الحق ، وهذا إخبار عن الواقع ، وإن كانوا مأمورين بالعبادة حسب الشرع والعقل.` },
            { text: "وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ", tafsir: `في المستقبل ( ما عَبَدْتُّمْ ) من الأصنام.` },
            { text: "وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ", tafsir: `في المستقبل ( ما أَعْبُدُ ) أنا ، وحيث إن الجملة الاسمية تدل على الدوام والثبوت فسرنا الآيتين ب « المستقبل » ، بخلاف الجملة الأولى حيث كانت فعلا وظاهر الفعل « الحال » وعطفنا عليه الجملة الثانية سياقا.` },
            { text: "لَكُمْ دِينُكُمْ وَلِىَ دِينِ", tafsir: `` }
        ]
    },
    110: { // سورة النصر
        name: "النصر",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ", tafsir: `. قالوا : وذلك لأنها دلت على تمام مهمة الرسول ( إِذا جاءَ ) يا رسول الله ( نَصْرُ اللهِ ) لدينه على سائر الأديان ، وللمسلمين على الكفار ( وَالْفَتْحُ ) أي جاء فتح مكة ، بأن فتحت عاصمة الوثنية والشرك في الجزيرة ، مما أخضع الجزيرة فتحها.` },
            { text: "وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا", tafsir: `يا رسول الله ( النَّاسَ ) القبائل وغيرهم ( يَدْخُلُونَ فِي دِينِ اللهِ ) الإسلام ( أَفْواجاً ) أي فوجا بعد فوج ، وجماعة بعد جماعة.` },
            { text: "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ إِنَّهُۥ كَانَ تَوَّابًۢا", tafsir: `` }
        ]
    },
    111: { // سورة المسد
        name: "المسد",
        basmalaTafsir: ``,
        verses: [
            { text: "تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ", tafsir: `` },
            { text: "مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ", tafsir: `أي عن أبي لهب ( مالُهُ ) أي ما نفعه في دفع العذاب عنه ( وَما كَسَبَ ) أي ما عمل من الكفر والآثام وإيذاء الرسول ، و « ما » موصولة عائدها محذوف ، أي ما كسبها.` },
            { text: "سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ", tafsir: `في الآخرة ، أي يدخل النار ملازما لها ( ناراً ذاتَ لَهَبٍ ) أي اشتعال وتوقد ، كما كان هو « أبا لهب » ، باعتبار أن وجنتيه محمرتان كأنهما ملتهبتان من شدة البريق.` },
            { text: "وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ", tafsir: `أي تبت وخسرت امرأته ، أعني ( حَمَّالَةَ الْحَطَبِ ) وسميت بهذا الاسم لأنها كانت تحمل الشوك كما تقدم ، ونصب « حمالة » على الذم ، كما قال ابن مالك : واقطع أو اتبع إن يكن معينا بدونها أو بعضها اقطع معلنا فِي جِيدِها حَبْلٌ مِنْ مَسَدٍ (5) وارفع أو انصب إن قطعت مضمرا مبتدءا أو ناصبا لن يظهرا` },
            { text: "فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ", tafsir: `` }
        ]
    },
    112: { // سورة الإخلاص
        name: "الإخلاص",
        basmalaTafsir: ``,
        verses: [
            { text: "قُلْ هُوَ ٱللَّهُ أَحَدٌ", tafsir: `( قُلْ ) يا رسول الله ( هُوَ ) ربي الذي أدعو إليه ( اللهُ أَحَدٌ ) لا شريك له ولا جزء.` },
            { text: "ٱللَّهُ ٱلصَّمَدُ", tafsir: `« الصمد » لغة : بمعنى السيد المقصود الذي لا يقضي أمر إلا بإذنه ، يعني أنه السيد المطلق الذي بيده كل شيء ، فلا يقع أمر في الكون إلا بإذنه وأمره.` },
            { text: "لَمْ يَلِدْ وَلَمْ يُولَدْ", tafsir: `أحدا ، فليست الملائكة بناته ـ كما زعم الكفار ـ ولا المسيح وعزير واليهود والنصارى أبناؤه ـ كما زعم أهل الكتاب ـ ( وَلَمْ يُولَدْ ) من أحد ، فلا أب له ولا أم.` },
            { text: "وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ", tafsir: `` }
        ]
    },
    113: { // سورة الفلق
        name: "الفلق",
        basmalaTafsir: ``,
        verses: [
            { text: "قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ", tafsir: `يا رسول الله ( أَعُوذُ ) أي أعتصم وأستجير من المكاره ( بِرَبِّ الْفَلَقِ ) « الفلق » هو الصبح ، وأصله الشق ، لأن الظلمة تنشق عنه.` },
            { text: "مِن شَرِّ مَا خَلَقَ", tafsir: `أي شر كل ما خلقه الله سبحانه من المؤذيات ، إنسانا كان أو جنا أو حيوانا أو جمادا كالسيل والعواصف.` },
            { text: "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", tafsir: `أي الليل ، من « الغسق » بمعنى الظلمة ( إِذا وَقَبَ ) أي إذا دخل ، فإن كثيرا من الشرور يتوجه إلى الإنسان في الليل وفي ظلامه ، حيث العيون نائمة ، والظلام مخيم.` },
            { text: "وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ", tafsir: `جمع « نفاثة » وهي المرأة الساحرة التي تنفث ـ أي تنفخ ـ في الشيء الذي عقد السحر به ، و « عقد » جمع عقدة ، فإن الساحرة تعقد الخيط بقصد عقد حظ أحد ، أو عقده عن زوجته ، ثم تنفث في تلك العقدة بسحرها وأورادها ، والسحر له أثر ، كما ثبت في علم النفس ، ودلت على ذلك التجربة.` },
            { text: "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", tafsir: `` }
        ]
    },
    114: { // سورة الناس
        name: "الناس",
        basmalaTafsir: ``,
        verses: [
            { text: "قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ", tafsir: `يا رسول الله ( أَعُوذُ ) أي أستجير وأعتصم من الشرور ( بِرَبِّ النَّاسِ ) خالقهم ومربيهم.` },
            { text: "مَلِكِ ٱلنَّاسِ", tafsir: `فهو المالك المطلق لهم ، لا ملك غيره وسائر الملوك إنما هم صوريون ، لا حقيقة لملوكيتهم إلا الاعتبار.` },
            { text: "إِلَٰهِ ٱلنَّاسِ", tafsir: `الذي هو إلههم ، فليست الأصنام آلهة كما يزعم الكفار ، فهو « رب » و « ملك » و « إله » فتربية الناس منه ، وسيدهم المالك لهم هو ، ومعبودهم الذي لا معبود سواه هو سبحانه.` },
            { text: "مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ", tafsir: `أي أعوذ بالله من شر الشيء الذي يوسوس للإنسان ، ليلقيه في الكفر والعصيان ، وأصله من « الوسوسة » وهي الصوت الخفي ، فإن من يريد الإغواء من إنس أو شيطان يخفي الصوت في أذن الشخص أو صدره ، حتى يضله ويلقيه في المعصية ( الْخَنَّاسِ ) من « خنس » بمعنى اختفى ، وذلك لأن من يريد الإضلال كثير الاختفاء ، أما الشيطان فواضح ، وأما الإنسان فإنه إذا أراد الإضلال يخفي نفسه لئلا يراه أحد فيحبط وسوسته ، وتظهر مكيدته للناس فيزدرونه ويطردونه.` },
            { text: "ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ", tafsir: `أما وسوسة الشيطان في الصدر فواضح ، وكونه في الصدر لأن الوسوسة في القلب والقلب في الصدر ، وأما وسوسة الإنسان فيه فلأنه يلقي الكلام إلى القلب ـ من مِنَ الْجِنَّةِ وَالنَّاسِ (6) الأذن ـ والقلب في الصدر.` },
            { text: "مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ", tafsir: `` }
        ]
    }
});
